﻿/* ═══════════════════════ DASHBOARD.JS ═══════════════════════
   Class management: list, create, edit, delete
═══════════════════════════════════════════════════════════ */

const Dashboard = (() => {

  let currentTeacher = null;

  function init(teacher) {
    currentTeacher = teacher;
    const nameEl = document.getElementById('teacher-name');
    nameEl.textContent = `${teacher.name} 老师`;
    document.getElementById('teacher-name').onclick = showEditNameModal;
    document.getElementById('btn-logout').onclick = Auth.logout;
    document.getElementById('btn-create-class').onclick = showCreateClassModal;

    // Multi-device sync refresh
    window.addEventListener('pets-data-sync', () => {
      if (App.currentPage === 'dashboard') render();
    });

    render();
  }

  function showEditNameModal() {
    const name = (currentTeacher==null?void 0:currentTeacher.name) || '';
    UI.openModal('修改姓名', `
    <div class="modal-form">
      <div class="form-field">
        <label>教师姓名</label>
        <input type="text" id="edit-teacher-name" placeholder="请输入姓名" maxlength="50">
      </div>
      <div class="modal-footer">
        <button class="btn-ghost" onclick="UI.closeModal()">取消</button>
        <button class="btn-primary" id="save-teacher-name-btn">保存</button>
      </div>
    </div>`, { narrow: true });
    const input = document.getElementById('edit-teacher-name');
    input.value = name;
    input.focus();
    document.getElementById('save-teacher-name-btn').onclick = async () => {
      const newName = document.getElementById('edit-teacher-name').value.trim();
      if (!newName) { UI.toast('姓名不能为空', 'warning'); return; }
      const result = await Store.apiChangeName(newName);
      if (!result.ok) {
        UI.toast(result.msg || '修改失败', 'error');
        if (result.msg && result.msg.includes('重新登录')) App.goto('auth');
        return;
      }
      currentTeacher = result.teacher;
      Store.teachers.upsert(result.teacher);
      Store.session.set(result.teacher);
      document.getElementById('teacher-name').textContent = `${result.teacher.name} 老师`;
      UI.closeModal();
      UI.toast('姓名已更新', 'success');
    };
  }

  function render() {
    const classes = Store.classes.byTeacher(currentTeacher.id);
    const grid = document.getElementById('classes-grid');
    if (classes.length === 0) {
      grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:4rem;color:var(--text-muted)">
        <div style="font-size:4rem;margin-bottom:1rem;opacity:.4">🏫</div>
        <p style="font-size:1.1rem">暂无班级，点击「创建班级」开始吧！</p>
      </div>`;
      return;
    }
    grid.innerHTML = classes.map(cls => classCardHtml(cls)).join('');
    grid.querySelectorAll('.class-card-enter').forEach(btn => {
      btn.onclick = e => {
        e.stopPropagation();
        App.enterClass(btn.dataset.id);
      };
    });
    grid.querySelectorAll('.class-card-edit').forEach(btn => {
      btn.onclick = e => { e.stopPropagation(); showEditClassModal(btn.dataset.id); };
    });
    grid.querySelectorAll('.class-card-delete').forEach(btn => {
      btn.onclick = e => { e.stopPropagation(); deleteClass(btn.dataset.id); };
    });
  }

  function getCumulativeScore(s) {
    return getLeaderboardWelfareScore(s);
  }

  function classCardHtml(cls) {
    const students = Store.students.byClass(cls.id);
    const count = students.length;
    const avgScore = count
      ? Math.round(students.reduce((s, t) => s + getCumulativeScore(t), 0) / count)
      : 0;
    const gradeStr = cls.grade || '未设置年级';
    return `
    <div class="class-card">
      <div class="class-card-banner">
        <div class="class-card-banner-title">${cls.name}</div>
      </div>
      <div class="class-card-body">
        <div class="class-card-grade">🎓 ${gradeStr}</div>
        <div class="class-card-stats">
          <div class="class-card-stat">
            <div class="stat-val">${count}</div>
            <div class="stat-label">学生人数</div>
          </div>
          <div class="class-card-stat">
            <div class="stat-val">${avgScore}</div>
            <div class="stat-label">平均积分</div>
          </div>
        </div>
        <div class="class-card-actions">
          <button class="btn-primary btn-sm class-card-enter" data-id="${cls.id}">进入班级 →</button>
          <button class="btn-ghost btn-sm class-card-edit" data-id="${cls.id}">编辑</button>
          <button class="btn-ghost btn-sm class-card-delete" data-id="${cls.id}" style="color:var(--danger);border-color:rgba(239,68,68,.3)">删除</button>
        </div>
      </div>
    </div>`;
  }

  function showCreateClassModal() {
    UI.openModal('创建班级', classFormHtml(), { narrow: true });
    document.getElementById('save-class-btn').onclick = () => {
      const name = document.getElementById('cls-name').value.trim();
      const grade = document.getElementById('cls-grade').value;
      if (!name) { UI.toast('请输入班级名称', 'warning'); return; }
      Store.classes.create({ teacherId: currentTeacher.id, name, grade });
      UI.closeModal();
      UI.toast('班级创建成功', 'success');
      render();
    };
  }

  function showEditClassModal(id) {
    const cls = Store.classes.find(id);
    if (!cls) return;
    UI.openModal('编辑班级', classFormHtml(cls), { narrow: true });
    document.getElementById('save-class-btn').onclick = () => {
      const name = document.getElementById('cls-name').value.trim();
      const grade = document.getElementById('cls-grade').value;
      if (!name) { UI.toast('请输入班级名称', 'warning'); return; }
      Store.classes.update(id, { name, grade });
      UI.closeModal();
      UI.toast('班级已更新', 'success');
      render();
    };
  }

  function classFormHtml(cls = {}) {
    return `
    <div class="modal-form">
      <div class="form-field">
        <label>班级名称</label>
        <input type="text" id="cls-name" value="${cls.name || ''}" placeholder="例如：三年(2)班">
      </div>
      <div class="form-field">
        <label>年级</label>
        <input type="text" id="cls-grade" value="${cls.grade || ''}" placeholder="例如：三年级、初二、高一">
      </div>
      <div class="modal-footer">
        <button class="btn-ghost" onclick="UI.closeModal()">取消</button>
        <button class="btn-primary" id="save-class-btn">${cls.id ? '保存' : '创建'}</button>
      </div>
    </div>`;
  }

  function deleteClass(id) {
    const cls = Store.classes.find(id);
    if (!cls) return;
    const count = Store.students.byClass(id).length;
    UI.confirm(
      `确定要删除「${cls.name}」吗？<br>将同时删除班级内 <b>${count}</b> 名学生及所有记录。`,
      () => {
        Store.deleteClass(id);
        UI.toast('班级已删除', 'success');
        render();
      },
      '删除班级'
    );
  }

  return { init, render };
})();

js/screen-lock.js:
/* ═══════════════════════ SCREEN-LOCK.JS ═══════════════════════
   班级页「锁屏」：本地密码遮罩，防离开座位时被操作。
   忘记密码：退出登录（清除锁屏数据）后重新登录。
═══════════════════════════════════════════════════════════════ */

const ScreenLock = (() => {
  const CRED_KEY = 'mc_screen_lock_cred_v1';
  const ACTIVE_KEY = 'mc_screen_lock_active_v1';

  function fnv1a(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return (h >>> 0).toString(16);
  }

  function hashPw(salt, password) {
    return fnv1a(`${salt}\n${password}`);
  }

  function randomSalt() {
    return `${Math.random().toString(36).slice(2)}${Date.now().toString(36)}`;
  }

  function savePassword(password) {
    const salt = randomSalt();
    const hash = hashPw(salt, password);
    localStorage.setItem(CRED_KEY, JSON.stringify({ salt, hash }));
  }

  function verifyPassword(password) {
    try {
      const raw = localStorage.getItem(CRED_KEY);
      if (!raw) return false;
      const { salt, hash } = JSON.parse(raw);
      if (!salt || !hash) return false;
      return hashPw(salt, password) === hash;
    } catch(e) {
      return false;
    }
  }

  function hasCredentials() {
    try {
      const raw = localStorage.getItem(CRED_KEY);
      if (!raw) return false;
      const o = JSON.parse(raw);
      return !!(o && o.salt && o.hash);
    } catch(e) {
      return false;
    }
  }

  function clearCredentials() {
    localStorage.removeItem(CRED_KEY);
    localStorage.removeItem(ACTIVE_KEY);
    hideOverlay();
  }

  function setActive(locked) {
    if (locked) localStorage.setItem(ACTIVE_KEY, '1');
    else localStorage.removeItem(ACTIVE_KEY);
  }

  function isActive() {
    return localStorage.getItem(ACTIVE_KEY) === '1';
  }

  function showUnlockModal() {
    const el = document.getElementById('screen-lock-overlay');
    if (!el) return;
    el.classList.add('open');
    el.setAttribute('aria-hidden', 'false');
    const inp = document.getElementById('screen-lock-input');
    if (inp) {
      inp.value = '';
      setTimeout(() => inp.focus(), 120);
    }
  }

  function hideUnlockModal() {
    const el = document.getElementById('screen-lock-overlay');
    if (!el) return;
    el.classList.remove('open');
    el.setAttribute('aria-hidden', 'true');
  }

  function enterLockMode() {
    document.body.classList.add('screen-lock-on');
    const bar = document.getElementById('screen-lock-bar');
    const guard = document.getElementById('screen-lock-guard');
    if (bar) bar.setAttribute('aria-hidden', 'false');
    if (guard) guard.setAttribute('aria-hidden', 'false');
  }

  function exitLockMode() {
    document.body.classList.remove('screen-lock-on');
    const bar = document.getElementById('screen-lock-bar');
    const guard = document.getElementById('screen-lock-guard');
    if (bar) bar.setAttribute('aria-hidden', 'true');
    if (guard) guard.setAttribute('aria-hidden', 'true');
    hideUnlockModal();
  }

  // 为兼容旧调用保留名称
  function showOverlay() {
    enterLockMode();
    showUnlockModal();
  }

  function hideOverlay() {
    exitLockMode();
  }

  function unlockWithPassword(pw) {
    if (!verifyPassword(pw)) {
      if (typeof UI !== 'undefined') UI.toast('密码错误', 'error');
      return false;
    }
    setActive(false);
    exitLockMode();
    if (typeof UI !== 'undefined') UI.toast('已解锁', 'success');
    return true;
  }

  function bindOverlayOnce() {
    if (window._mcScreenLockBound) return;
    window._mcScreenLockBound = true;
    const unlockBtn = document.getElementById('screen-lock-unlock-btn');
    const inp = document.getElementById('screen-lock-input');
    const forgotBtn = document.getElementById('screen-lock-forgot-btn');
    const closeBtn = document.getElementById('screen-lock-close-btn');
    const guard = document.getElementById('screen-lock-guard');
    const overlay = document.getElementById('screen-lock-overlay');
    if (unlockBtn) {
      unlockBtn.onclick = () => unlockWithPassword(inp && inp.value ? inp.value.trim() : '');
    }
    if (inp) {
      inp.addEventListener('keydown', e => {
        if (e.key === 'Enter') unlockWithPassword(inp.value ? inp.value.trim() : '');
      });
    }
    if (forgotBtn) {
      forgotBtn.onclick = async () => {
        const ok = window.confirm('将退出当前账号并清除锁屏，确定吗？退出后请重新登录。');
        if (!ok) return;
        clearCredentials();
        exitLockMode();
        if (typeof Auth !== 'undefined' && Auth.logout) await Auth.logout();
      };
    }
    if (closeBtn) {
      closeBtn.onclick = () => hideUnlockModal();
    }
    // 点击拦截层任意位置弹出解锁弹窗
    if (guard) {
      guard.addEventListener('click', () => {
        if (isActive()) showUnlockModal();
      });
    }
    // 点击解锁弹窗背景关闭弹窗（保留在锁定模式）
    if (overlay) {
      overlay.addEventListener('click', (e) => {
        if (e.target === overlay) hideUnlockModal();
      });
    }
  }

  function tryShowIfLocked() {
    bindOverlayOnce();
    if (!hasCredentials()) {
      setActive(false);
      return;
    }
    if (isActive()) {
      enterLockMode();
      showUnlockModal();
    }
  }

  function openSetupModal() {
    const body = `
      <p style="margin-bottom:1rem;color:var(--text-muted);font-size:.875rem;line-height:1.55">
        锁屏后需输入密码解锁。若<strong>忘记锁屏密码</strong>，请点击班级列表页右上角「退出登录」重新登录即可（锁屏信息会清除）。
      </p>
      <div class="form-field" style="margin-bottom:.75rem">
        <label>锁屏密码</label>
        <input type="password" id="sl-setup-pw1" class="filter-input" style="width:100%" placeholder="至少 4 位" autocomplete="off">
      </div>
      <div class="form-field" style="margin-bottom:1rem">
        <label>确认密码</label>
        <input type="password" id="sl-setup-pw2" class="filter-input" style="width:100%" placeholder="再次输入" autocomplete="off">
      </div>
      <div class="modal-footer">
        <button type="button" class="btn-ghost" onclick="UI.closeModal()">取消</button>
        <button type="button" class="btn-primary" id="sl-setup-confirm">确认锁屏</button>
      </div>`;
    UI.openModal('🔒 设置锁屏密码', body, { narrow: true });
    document.getElementById('sl-setup-confirm').onclick = () => {
      const p1 = document.getElementById('sl-setup-pw1').value.trim();
      const p2 = document.getElementById('sl-setup-pw2').value.trim();
      if (p1.length < 4) {
        UI.toast('密码至少 4 位', 'warning');
        return;
      }
      if (p1 !== p2) {
        UI.toast('两次密码不一致', 'warning');
        return;
      }
      savePassword(p1);
      setActive(true);
      UI.closeModal();
      bindOverlayOnce();
      enterLockMode();
      showUnlockModal();
    };
  }

  function requestLock() {
    bindOverlayOnce();
    if (!hasCredentials()) {
      openSetupModal();
      return;
    }
    setActive(true);
    enterLockMode();
    showUnlockModal();
  }

  return {
    requestLock,
    tryShowIfLocked,
    clearCredentials,
    hasCredentials,
    isActive,
    bindOverlayOnce,
  };
})();

js/realtime-sync.js:
/**
 * 实时同步客户端 - 使用长轮询实现准实时多设备同步
 * 无需 WebSocket，兼容性更好
 *
 * 工作原理：
 * 1. 写入数据后立即保存到服务器（版本号+1）
 * 2. 后台持续运行长轮询，等待服务器通知有新版本
 * 3. 收到通知后立即拉取最新数据并更新本地
 * 4. 实现延迟：通常 < 1秒（取决于服务器响应）
 */

const RealtimeSync = (() => {
  const API = 'backend/realtime-sync.php';

  let token = null;
  let localVersion = 0;
  let isPolling = false;
  let pollAbortController = null;
  let isSyncing = false;
  let pollRetryCount = 0;
  let isActive = false;

  // 回调函数
  const callbacks = {
    onUpdate: null,      // 收到更新时调用
    onSyncSuccess: null, // 同步成功时调用
    onError: null        // 错误时调用
  };

  /**
   * 启动实时同步
   * @param {string} userToken - 用户token
   * @param {number} initialVersion - 初始版本号
   * @param {object} cbs - 回调函数
   */
  function start(userToken, initialVersion = 0, cbs = {}) {
    if (isActive) {
      console.log('[实时同步] 已在运行');
      return;
    }

    token = userToken;
    localVersion = initialVersion;
    Object.assign(callbacks, cbs);
    isActive = true;

    console.log('[实时同步] 启动，初始版本:', localVersion);

    // 启动长轮询
    startLongPolling();
  }

  /**
   * 停止实时同步
   */
  function stop() {
    console.log('[实时同步] 停止');
    isActive = false;
    isPolling = false;

    if (pollAbortController) {
      pollAbortController.abort();
      pollAbortController = null;
    }
  }

  /**
   * 长轮询：持续等待服务器更新通知
   */
  async function startLongPolling() {
    if (!isActive || isPolling) return;

    isPolling = true;
    pollRetryCount = 0;

    while (isActive) {
      try {
        pollAbortController = new AbortController();

        // 发起长轮询请求（服务器会等待最多25秒）
        const response = await fetch(API + '?action=waitForUpdate', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            token: token,
            version: localVersion,
            timeout: 25
          }),
          signal: pollAbortController.signal
        });

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const result = await response.json();

        if (result.ok && result.hasUpdate) {
          // 收到更新通知
          pollRetryCount = 0;
          localVersion = result.version;

          console.log('[实时同步] 收到更新，版本:', localVersion);

          // 触发更新回调
          if (callbacks.onUpdate) {
            callbacks.onUpdate(result.data, result.version);
          }
        }

        // 继续下一次轮询（无延迟，立即重连）
        if (isActive) {
          await new Promise(resolve => setTimeout(resolve, 100)); // 短暂延迟避免过于频繁
          continue;
        }

      } catch (error) {
        if (error.name === 'AbortError') {
          // 手动中止，正常退出
          break;
        }

        // 网络错误或其他异常
        pollRetryCount++;
        const retryDelay = Math.min(1000 * Math.pow(2, pollRetryCount - 1), 10000);

        console.warn(`[实时同步] 轮询失败，${retryDelay/1000}秒后重试 (第${pollRetryCount}次):`, error.message);

        if (callbacks.onError && pollRetryCount === 1) {
          callbacks.onError(error);
        }

        // 等待后重试
        await new Promise(resolve => setTimeout(resolve, retryDelay));
      }
    }

    isPolling = false;
  }

  /**
   * 同步数据到服务器
   * @param {object} data - 要同步的数据
   * @param {number} version - 当前版本号
   */
  async function syncData(data, version = 0) {
    if (isSyncing) {
      console.log('[实时同步] 同步中，跳过');
      return { ok: false, msg: 'syncing' };
    }

    isSyncing = true;

    try {
      const response = await fetch(API + '?action=save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          token: token,
          data: data,
          version: version || localVersion
        })
      });

      const result = await response.json();

      if (response.ok && result.ok) {
        localVersion = result.version;
        console.log('[实时同步] 同步成功，新版本:', localVersion);

        if (callbacks.onSyncSuccess) {
          callbacks.onSyncSuccess(result.version);
        }

        return { ok: true, version: result.version };
      } else {
        console.error('[实时同步] 同步失败:', result.msg);
        if (callbacks.onError) {
          callbacks.onError(new Error(result.msg || '同步失败'));
        }
        return { ok: false, msg: result.msg };
      }

    } catch (error) {
      console.error('[实时同步] 同步异常:', error);
      if (callbacks.onError) {
        callbacks.onError(error);
      }
      return { ok: false, msg: error.message };
    } finally {
      isSyncing = false;
    }
  }

  /**
   * 立即拉取最新数据（不等待）
   */
  async function pullData() {
    try {
      const response = await fetch(API + '?action=load', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token: token })
      });

      const result = await response.json();

      if (response.ok && result.ok) {
        localVersion = result.version;
        console.log('[实时同步] 拉取数据成功，版本:', localVersion);
        return { ok: true, data: result.data, version: result.version };
      } else {
        return { ok: false, msg: result.msg };
      }

    } catch (error) {
      console.error('[实时同步] 拉取数据异常:', error);
      return { ok: false, msg: error.message };
    }
  }

  /**
   * 获取当前状态
   */
  function getStatus() {
    return {
      active: isActive,
      polling: isPolling,
      syncing: isSyncing,
      version: localVersion,
      retryCount: pollRetryCount
    };
  }

  return {
    start,
    stop,
    syncData,
    pullData,
    getStatus
  };
})();

js/groups.js:
/* ═══════════════════════ GROUPS.JS ═══════════════════════
   Group management - CRUD + student assignment
   ───────────────────────────────────────────────────────── */

const Groups = (() => {

  let currentClassId = null;

  function init(classId) {
    currentClassId = classId;
    document.getElementById('btn-create-group').onclick = () => showCreateModal();
    // Only render if tab is visible
    if (document.getElementById('tab-groups').classList.contains('active')) {
      render();
    }
  }

  function render() {
    const container = document.getElementById('groups-list');
    if (!container) return;
    // Only render if tab is active
    const tab = document.getElementById('tab-groups');
    if (tab && !tab.classList.contains('active')) return;

    const groups = Store.groups.byClass(currentClassId);
    const students = Store.students.byClass(currentClassId);

    if (groups.length === 0) {
      container.innerHTML = `<div style="text-align:center;padding:3rem;color:var(--text-muted)">
        <div style="font-size:3rem;margin-bottom:.75rem;opacity:.4">👥</div>
        <p>还没有小组，点击「创建小组」按钮添加</p>
      </div>`;
      return;
    }

    container.innerHTML = groups.map(g => {
      const members = students.filter(s => s.groupIds && s.groupIds.includes(g.id));
      return `
      <div class="group-card" style="border-left-color:${g.color}">
        <div class="group-card-header">
          <div class="group-card-name">
            <span class="group-color-dot" style="background:${g.color}"></span>
            ${g.name}
            <span style="font-weight:400;color:var(--text-muted);font-size:.875rem">(${members.length}人)</span>
          </div>
          <div class="group-card-actions">
            <button class="btn-ghost btn-sm" onclick="Groups._addMember('${g.id}')">＋ 添加成员</button>
            <button class="btn-ghost btn-sm" onclick="Groups._edit('${g.id}')">编辑</button>
            <button class="btn-ghost btn-sm" style="color:var(--danger)" onclick="Groups._delete('${g.id}')">删除</button>
          </div>
        </div>
        <div class="group-members">
          ${members.map(s => `
            <span class="group-member-tag">
              ${s.name}
              <span class="remove-from-group" title="移出小组"
                onclick="Groups._removeMember('${s.id}', '${g.id}')">✕</span>
            </span>`).join('')}
          ${members.length === 0 ? '<span style="color:var(--text-muted);font-size:.85rem">暂无成员</span>' : ''}
        </div>
      </div>`;
    }).join('');
  }

  function showCreateModal(data) {
    UI.openModal(data ? '编辑小组' : '创建小组', groupFormHtml(data), { narrow: true });
    document.getElementById('save-group-btn').onclick = () => saveGroup(data ? data.id : null);
  }

  function groupFormHtml(g) {
    return `
    <div class="modal-form">
      <div class="form-field">
        <label>小组名称</label>
        <input type="text" id="g-name" value="${g ? g.name : ''}" placeholder="例如：红队、第一组">
      </div>
      <div class="form-field">
        <label>小组颜色</label>
        <div class="color-picker-row">
          ${GROUP_COLORS.map(c => `<span class="color-swatch ${g && g.color === c ? 'selected' : ''}"
            style="background:${c}" data-color="${c}"
            onclick="document.querySelectorAll('.color-swatch').forEach(s=>s.classList.remove('selected'));this.classList.add('selected')"></span>`
    ).join('')}
        </div>
      </div>
      <div class="modal-footer">
        <button class="btn-ghost" onclick="UI.closeModal()">取消</button>
        <button class="btn-primary" id="save-group-btn">${g ? '保存' : '创建'}</button>
      </div>
    </div>`;
  }

  function saveGroup(id) {
    const name = document.getElementById('g-name').value.trim();
    const colorEl = document.querySelector('.color-swatch.selected');
    const color = colorEl ? colorEl.dataset.color : GROUP_COLORS[0];
    if (!name) { UI.toast('请输入小组名称', 'warning'); return; }
    if (id) {
      Store.groups.update(id, { name, color });
      UI.toast('小组已更新', 'success');
    } else {
      Store.groups.create({ classId: currentClassId, name, color });
      UI.toast('小组已创建', 'success');
    }
    UI.closeModal();
    render();
    Students.render();  // refresh student cards' stripe colors
  }

  function _edit(id) {
    const g = Store.groups.find(id);
    if (g) showCreateModal(g);
  }

  function _delete(id) {
    const g = Store.groups.find(id);
    if (!g) return;
    const members = Store.students.byClass(currentClassId).filter(s => s.groupIds && s.groupIds.includes(id));
    UI.confirm(
      `确定删除小组「${g.name}」吗？${members.length ? `<br>${members.length}名成员将被移出小组。` : ''}`,
      () => {
        Store.groups.remove(id);
        UI.toast('小组已删除', 'success');
        render();
        Students.render();
      }
    );
  }

  function _addMember(groupId) {
    const g = Store.groups.find(groupId);
    const candidates = Store.students.byClass(currentClassId)
      .filter(s => !s.groupIds || !s.groupIds.includes(groupId));
    if (candidates.length === 0) { UI.toast('没有可添加的学生', 'info'); return; }

    const renderCandidates = (keyword = '') => {
      const kw = keyword.trim();
      const list = kw
        ? candidates.filter(s => {
          const pn = ((getPet(s.petType)==null?void 0:getPet(s.petType)).name || '').toLowerCase();
          return s.name.includes(keyword) || pn.includes(kw.toLowerCase());
        })
        : candidates;
      return list.map(s => {
        const p = s.petType ? getPet(s.petType) : null;
        const petLine = p ? `<div class="am-pet">${p.emoji} ${p.name}</div>` : '';
        return `
        <div class="am-card ${s._checked ? 'am-card--selected' : ''}" data-id="${s.id}">
          <span class="am-check">✓</span>
          <div class="am-info">
            <div class="am-name">${s.name}</div>
            ${petLine}
          </div>
          ${(s.groupIds && s.groupIds.length > 0)
            ? `<span class="am-cur-group">当前在: ${(Store.groups.find(s.groupIds[0])==null?void 0:Store.groups.find(s.groupIds[0])).name || '其他组'}</span>`
            : ''}
        </div>`;
      }).join('') || '<p style="color:var(--text-muted);text-align:center;padding:1.5rem 0">没有匹配的学生</p>';
    };

    UI.openModal(`➕ 添加成员 — ${g ? g.name : ''}`, `
      <div class="modal-form">
        <div class="am-toolbar">
          <input type="text" id="am-search" placeholder="🔍 搜索姓名 / 宠物" class="am-search-input">
          <span id="am-count" class="am-count">已选 0 人</span>
        </div>
        <div class="am-select-all-row">
          <button class="btn-ghost btn-sm" id="am-select-all">全选</button>
          <button class="btn-ghost btn-sm" id="am-clear-all">清空</button>
        </div>
        <div id="am-list" class="am-list">${renderCandidates()}</div>
        <div class="modal-footer">
          <button class="btn-ghost" onclick="UI.closeModal()">取消</button>
          <button class="btn-primary" id="do-add-member-btn">确认添加</button>
        </div>
      </div>`, { wide: true });

    // 状态：已勾选的 id 集合
    const selected = new Set();

    const updateCount = () => {
      document.getElementById('am-count').textContent = `已选 ${selected.size} 人`;
    };

    const rebindCards = () => {
      document.querySelectorAll('.am-card').forEach(card => {
        const id = card.dataset.id;
        card.classList.toggle('am-card--selected', selected.has(id));
        card.onclick = () => {
          selected.has(id) ? selected.delete(id) : selected.add(id);
          card.classList.toggle('am-card--selected', selected.has(id));
          updateCount();
        };
      });
    };

    rebindCards();

    document.getElementById('am-search').oninput = function () {
      document.getElementById('am-list').innerHTML = renderCandidates(this.value.trim());
      rebindCards();
    };

    document.getElementById('am-select-all').onclick = () => {
      document.querySelectorAll('.am-card').forEach(card => selected.add(card.dataset.id));
      rebindCards(); updateCount();
    };
    document.getElementById('am-clear-all').onclick = () => {
      selected.clear(); rebindCards(); updateCount();
    };

    // footer 已被 openModal 移走重建，需 setTimeout 确保新 DOM 节点可被找到
    setTimeout(() => {
      const confirmBtn = document.getElementById('do-add-member-btn');
      if (!confirmBtn) return;
      confirmBtn.onclick = () => {
        if (selected.size === 0) { UI.toast('请先选择学生', 'warning'); return; }
        selected.forEach(id => {
          const s = Store.students.find(id);
          const existing = (s && s.groupIds) ? s.groupIds : [];
          const newIds = existing.includes(groupId) ? existing : [...existing, groupId];
          Store.students.update(id, { groupIds: newIds, groupId: newIds[0] || null });
        });
        UI.closeModal();
        UI.toast(`已添加 ${selected.size} 名成员`, 'success');
        render();
        Students.render();
      };
    }, 0);
  }

  function _removeMember(studentId, groupId) {
    const s = Store.students.find(studentId);
    if (!s) return;
    const newGroupIds = (s.groupIds || []).filter(id => id !== groupId);
    Store.students.update(studentId, { groupIds: newGroupIds, groupId: newGroupIds[0] || null });
    render();
    Students.render();
  }

  return { init, render, _edit, _delete, _addMember, _removeMember };
})();

js/records.js:
/* ═══════════════════════ RECORDS.JS ═══════════════════════
   Score records - list and filter（按学生维度分组展示 + 导出）
═══════════════════════════════════════════════════════════ */

const Records = (() => {

  let currentClassId = null;

  const TYPE_ICONS = { add: '➕', deduct: '➖', feed: '🍗', redeem: '🛒' };
  const TYPE_LABELS = { add: '加分', deduct: '扣分', feed: '投喂', redeem: '兑换' };

  function init(classId) {
    currentClassId = classId;
    document.getElementById('records-filter-type').onchange = () => render(classId);
    document.getElementById('records-filter-student').onchange = () => render(classId);
    const modeEl = document.getElementById('records-filter-mode');
    if (modeEl) modeEl.onchange = () => render(classId);
    const exp = document.getElementById('btn-records-export');
    if (exp) exp.onclick = () => exportFilteredCsv();
    // Only render if tab is visible
    if (document.getElementById('tab-records').classList.contains('active')) {
      render(classId);
    }
  }

  /** 与列表一致：当前班级 + 类型/学生筛选，时间新→旧（不含投喂：投喂单独记一条仅用于喂养进度，非班级积分流水） */
  function getFilteredRecords() {
    if (!currentClassId) return [];
    const typeFilter = (document.getElementById('records-filter-type') ? document.getElementById('records-filter-type').value : '') || '';
    const studentFilter = (document.getElementById('records-filter-student') ? document.getElementById('records-filter-student').value : '') || '';
    let records = Store.records.byClass(currentClassId)
      .filter(r => r.type !== 'feed')
      .sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
    if (typeFilter) records = records.filter(r => r.type === typeFilter);
    if (studentFilter) records = records.filter(r => r.studentId === studentFilter);
    return records;
  }

  function csvCell(v) {
    const s = String(v || '');
    if (/[",\r\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
    return s;
  }

  /** 导出当前筛选结果为 CSV（UTF-8 BOM，Excel 可直接打开） */
  function exportFilteredCsv() {
    const records = getFilteredRecords();
    if (records.length === 0) {
      if (typeof UI !== 'undefined') UI.toast('没有可导出的记录', 'warning');
      return;
    }
    const headers = ['时间', '学生姓名', '宠物名称', '类型', '变动值', '说明', '记录ID'];
    const rows = records.map((r) => {
      const st = r.studentId ? Store.students.find(r.studentId) : null;
      const petName = (st||{}).petType ? ((getPet(st.petType) || {}).name || st.petType) : '';
      const typeZh = TYPE_LABELS[r.type] || r.type || '';
      let valueStr = '';
      if (r.type === 'feed') {
        const n = r.fedAmount != null ? r.fedAmount : 1;
        valueStr = `投喂 ${n}🍗`;
      } else if (r.type === 'redeem') {
        valueStr = `-${Math.abs(r.amount || 0)} 积分`;
      } else {
        valueStr = `${r.amount}`;
      }
      const t = r.createdAt
        ? new Date(r.createdAt).toLocaleString('zh-CN', { hour12: false })
        : '';
      return [t, r.studentName || '', petName, typeZh, valueStr, r.reason || '', r.id || ''];
    });
    const csv = '\uFEFF' + [headers.map(csvCell).join(','), ...rows.map(cols => cols.map(csvCell).join(','))].join('\r\n');
    const cls = typeof Store !== 'undefined' && Store.classes ? Store.classes.find(currentClassId) : null;
    const safeClass = String((cls||{}).name || '班级').replace(/[/\\:*?"<>|]/g, '_');
    const day = new Date().toLocaleDateString('zh-CN').replace(/\//g, '-');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = `${safeClass}_积分记录_${day}.csv`;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    setTimeout(function() { document.body.removeChild(a); URL.revokeObjectURL(url); }, 100);
    if (typeof UI !== 'undefined') UI.toast(`已导出 ${records.length} 条记录`, 'success');
  }

  /** 班级内记录 → 按 studentId 分组，组内时间倒序；组顺序按该生「最新一条」时间倒序 */
  function groupRecordsByStudent(records) {
    const map = new Map();
    for (const r of records) {
      const sid = r.studentId || '';
      const key = sid || '__orphan__';
      if (!map.has(key)) map.set(key, []);
      map.get(key).push(r);
    }
    for (const [, arr] of map) {
      arr.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    }
    return [...map.entries()].sort((a, b) => {
      const ta = a[1].length ? new Date(a[1][0].createdAt).getTime() : 0;
      const tb = b[1].length ? new Date(b[1][0].createdAt).getTime() : 0;
      return tb - ta;
    });
  }

  function recordItemHtml(r) {
    const s = Store.students.find(r.studentId);
    const petType = s ? s.petType : null;
    const petSrc = petType ? getPetImg(petType, 1) : '';
    const typeClass = r.type === 'add' ? 'add' : (r.type === 'deduct' ? 'deduct' : 'feed');
    return `
      <div class="record-item" data-student-id="${r.studentId || ''}" data-record-id="${r.id || ''}">
        <div class="record-type-badge ${typeClass}">${TYPE_ICONS[r.type] || '📌'}</div>
        ${petSrc ? `<img src="${petSrc}" class="record-item-pet" alt=""
            onerror="this.style.display='none'">` : ''}
        <div class="record-info">
          <div class="record-name">${r.studentName || '未知学生'}</div>
          <div class="record-reason">${r.reason || TYPE_LABELS[r.type] || ''}</div>
        </div>
        <div class="record-amount ${typeClass}">${r.type === 'feed' ? '-1 🍗' : (r.type === 'redeem' ? `-${Math.abs(r.amount || 0)} 积分` : `${r.amount > 0 ? '+' : ''}${r.amount} 分`)}</div>
        <div class="record-time">${timeAgo(r.createdAt)}</div>
        <button class="record-undo-btn" data-undo-id="${r.id || ''}" title="撤回此操作">撤销</button>
      </div>`;
  }

  let _displayLimit = 200;

  function render(classId) {
    if (classId) {
      currentClassId = classId;
      _displayLimit = 200; // Reset limit when entering a new class or explicitly calling init
    }
    const container = document.getElementById('records-list');
    if (!container) return;
    // Only render if tab is active
    const tab = document.getElementById('tab-records');
    if (tab && !tab.classList.contains('active')) return;

    // Reset limit if it's a fresh render from tab switch (optional)
    // _displayLimit = 200; 

    const allRecords = getFilteredRecords();
    UI.populateRecordsStudentFilter(Store.students.byClass(currentClassId));

    if (allRecords.length === 0) {
      container.innerHTML = `<div style="text-align:center;padding:3rem;color:var(--text-muted)">
        <div style="font-size:3rem;opacity:.4;margin-bottom:.75rem">📝</div>
        <p>暂无积分记录</p>
      </div>`;
      return;
    }

    const records = allRecords.slice(0, _displayLimit);
    const hasMore = allRecords.length > _displayLimit;

    const studentFilter = document.getElementById('records-filter-student').value;
    const viewMode = (document.getElementById('records-filter-mode') ? document.getElementById('records-filter-mode').value : 'student') || 'student';
    let html = '';

    if (viewMode === 'time' || studentFilter) {
      html = records.map(r => recordItemHtml(r)).join('');
    } else {
      const groups = groupRecordsByStudent(records);
      html = groups.map(([sidKey, recs]) => {
        const sid = sidKey === '__orphan__' ? null : sidKey;
        const st = sid ? Store.students.find(sid) : null;
        const title = st ? st.name : ((recs[0] ? recs[0].studentName : '未知学生') || '未知学生');
        const petTag = (st==null?void 0:st.petType) ? ((getPet(st.petType) || {}).emoji || '') + ' ' + ((getPet(st.petType) || {}).name || '') : '';
        const body = recs.map(r => recordItemHtml(r)).join('');
        return `<section class="record-student-group">
          <header class="record-student-group__head">
            <span class="record-student-group__title">${title}${petTag ? ` · ${petTag}` : ''}</span>
            <span class="record-student-group__meta">${recs.length} 条</span>
          </header>
          <div class="record-student-group__list">${body}</div>
        </section>`;
      }).join('');
    }

    if (hasMore) {
      html += `
        <div style="text-align:center; padding:20px;">
          <button class="btn-ghost" id="btn-records-load-more" style="width:100%; max-width:300px; border:1px solid #e2e8f0;">
            显示更多记录 (当前展示前 ${_displayLimit} 条，共 ${allRecords.length} 条)
          </button>
        </div>`;
    }

    container.innerHTML = html;

    if (hasMore) {
      document.getElementById('btn-records-load-more').onclick = () => {
        _displayLimit += 500;
        render();
      };
    }

    container.querySelectorAll('.record-undo-btn').forEach(btn => {
      btn.onclick = (e) => {
        e.stopPropagation();
        undoRecord(btn.dataset.undoId);
      };
    });
  }

  function isAutoFeedFromScore(r) {
    if (r.type !== 'feed') return false;
    const reason = r.reason || '';
    return reason.startsWith('加分 (') || reason.startsWith('遥控加分 (') || reason.startsWith('加分自动投喂 (') || reason.startsWith('挑战成功自动投喂 (');
  }

  function undoRecord(recordId) {
    if (!recordId) return;
    const allRecords = Store.records.byClass(currentClassId);
    const target = allRecords.find(r => r.id === recordId);
    if (!target) { UI.toast('找不到该记录', 'error'); return; }

    const typeMap = { add: '加分', deduct: '扣分', feed: '投喂', redeem: '兑换' };
    const desc = `${target.studentName || '未知学生'} 的「${typeMap[target.type] || target.type}」操作（${target.amount > 0 ? '+' : ''}${target.amount}）`;

    UI.confirm(`确认撤回：${desc}？`, () => {
      const sid = target.studentId;
      let s = Store.students.find(sid);
      if (!s) { UI.toast('找不到学生', 'error'); return; }

      if (target.type === 'add' && target.amount > 0) {
        const tAdd = new Date(target.createdAt).getTime();
        const feeds = allRecords
          .filter(r =>
            r.studentId === sid &&
            r.type === 'feed' &&
            isAutoFeedFromScore(r) &&
            new Date(r.createdAt).getTime() >= tAdd
          )
          .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        for (const fr of feeds) {
          s = Store.students.find(sid);
          const fa = fr.fedAmount || 1;
          Store.students.update(sid, {
            fedLegs: Math.max(0, (s.fedLegs || 0) - fa),
            chickenLegs: (s.chickenLegs || 0) + fa,
          });
          Store.records.removeById(fr.id);
        }
        s = Store.students.find(sid);
        if (target.legsDeltaChicken != null && target.legsDeltaFed != null) {
          Store.students.update(sid, {
            chickenLegs: (s.chickenLegs || 0) - target.legsDeltaChicken,
            fedLegs: (s.fedLegs || 0) - target.legsDeltaFed,
          });
        } else {
          Store.students.update(sid, {
            chickenLegs: Math.max(0, (s.chickenLegs || 0) - (target.amount || 0)),
          });
        }
        Store.records.removeById(target.id);
      } else if (target.type === 'redeem') {
        const price = Math.abs(target.amount || 0);
        Store.students.update(sid, {
          shopRedeemDebt: Math.max(0, (s.shopRedeemDebt || 0) - price),
        });
        Store.records.removeById(target.id);
      } else if (target.legsDeltaChicken != null && target.legsDeltaFed != null) {
        Store.students.update(sid, {
          chickenLegs: (s.chickenLegs || 0) - target.legsDeltaChicken,
          fedLegs: (s.fedLegs || 0) - target.legsDeltaFed,
        });
        Store.records.removeById(target.id);
      } else {
        if (target.type === 'deduct' && target.amount < 0) {
          Store.students.update(sid, { chickenLegs: (s.chickenLegs || 0) + Math.abs(target.amount) });
        } else if (target.type === 'add' && target.amount > 0) {
          Store.students.update(sid, { chickenLegs: Math.max(0, (s.chickenLegs || 0) - (target.amount || 0)) });
        }
        Store.records.removeById(target.id);
      }

      UI.toast(`↩ 已撤回 ${target.studentName || '该学生'} 的操作`, 'success');
      Students.render();
      render(currentClassId);
    }, '确认撤回操作');
  }

  return { init, render, exportFilteredCsv, getFilteredRecords };
})();

js/announcements.js:
/* ═══════════════════════════════════════════════════════
   Remote Announcement Module (隔空喊话)
   Handles polling, displaying popups, and TTS reading.
   ═══════════════════════════════════════════════════════ */

const Announcements = (() => {
  let _pollTimer = null;
  let _isPolling = false;
  let _speechUnlocked = false;
  let _keepAliveAudio = null; // 后台保活用的静音循环音频
  let _sharedAudioCtx = null; // 共享 AudioContext，便于每次播报前 resume

  /** 创建/启动一个静音循环音频，保持标签在后台仍有音频活跃，
   *  这样浏览器不会暂停 speechSynthesis 与 AudioContext，实现最小化后仍能播报。 */
  function _ensureKeepAliveAudio() {
    if (_keepAliveAudio) {
      try { _keepAliveAudio.play().catch(() => {}); } catch (_) {}
      return;
    }
    try {
      const audio = document.createElement('audio');
      audio.loop = true;
      audio.setAttribute('playsinline', '');
      audio.setAttribute('webkit-playsinline', '');
      audio.preload = 'auto';
      audio.volume = 0.0001; // 近乎静音，但保持“正在播放音频”的状态
      // 一段极短的合法 WAV 静音（约 0.05 秒），base64 内联，避免外部依赖
      audio.src = 'data:audio/wav;base64,UklGRlIAAABXQVZFZm10IBAAAAABAAEARKwAAIhYAQACABAAZGF0YS4AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=';
      audio.style.display = 'none';
      document.body.appendChild(audio);
      const p = audio.play();
      if (p && p.catch) p.catch(() => {});
      _keepAliveAudio = audio;
    } catch (_) {}
  }

  function _ensureSharedAudioCtx() {
    if (_sharedAudioCtx) return _sharedAudioCtx;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      _sharedAudioCtx = new AC();
    } catch (_) {}
    return _sharedAudioCtx;
  }

  function _unlockSpeech() {
    if (_speechUnlocked || !window.speechSynthesis) return;
    const msg = new SpeechSynthesisUtterance('');
    msg.volume = 0;
    window.speechSynthesis.speak(msg);
    // 用户交互中同步启动静音音频与 AudioContext，规避后台受限
    _ensureKeepAliveAudio();
    const ctx = _ensureSharedAudioCtx();
    if (ctx && ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
    _speechUnlocked = true;
    document.removeEventListener('click', _unlockSpeech);
    document.removeEventListener('touchstart', _unlockSpeech);
  }

  function init() {
    document.addEventListener('click', _unlockSpeech);
    document.addEventListener('touchstart', _unlockSpeech);
    // 页面可见性变化时，尝试恢复音频/语音调度，保证从后台切回或后台唤醒后仍能播报
    document.addEventListener('visibilitychange', () => {
      try {
        if (_keepAliveAudio && _keepAliveAudio.paused) _keepAliveAudio.play().catch(() => {});
        if (_sharedAudioCtx && _sharedAudioCtx.state === 'suspended') _sharedAudioCtx.resume();
        if (window.speechSynthesis && window.speechSynthesis.paused) window.speechSynthesis.resume();
      } catch (_) {}
    });
    startPolling();
    _injectStyles();
  }

  function startPolling() {
    if (_isPolling) return;
    _isPolling = true;
    _poll();
  }

  async function _poll() {
    if (!_isPolling) return;
    const token = Store.getToken();
    if (!token) {
      setTimeout(_poll, 10000); // Wait longer if not logged in
      return;
    }

    try {
      const res = await fetch(Store.API + '?action=pollAnnouncements', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token })
      });
      const data = await res.json();
      if (data.ok && data.messages && data.messages.length > 0) {
        data.messages.forEach(msg => {
          const times = Math.max(1, parseInt(msg.repeat_count, 10) || 1);
          showPopup(msg.content, times);
        });
      }
    } catch (e) { console.error('Poll failed:', e); }

    _pollTimer = setTimeout(_poll, 5000); // Check every 5 seconds
  }

  function showPopup(content, repeatCount = 1) {
    const overlay = document.createElement('div');
    overlay.className = 'ra-overlay';
    const times = Math.max(1, parseInt(repeatCount, 10) || 1);
    overlay.innerHTML = `
      <div class="ra-modal">
        <div class="ra-header">📢 隔空喊话</div>
        <div class="ra-body">${content}</div>
        ${times > 1 ? `<div class="ra-repeat-hint">语音将播报 ${times} 次</div>` : ''}
        <button class="ra-close">我知道了</button>
      </div>
    `;
    document.body.appendChild(overlay);

    const closeBtn = overlay.querySelector('.ra-close');
    closeBtn.onclick = () => {
      // 关闭弹窗时中止未播完的循环播报
      try { window.speechSynthesis && window.speechSynthesis.cancel(); } catch (_) {}
      overlay.classList.add('fade-out');
      setTimeout(() => overlay.remove(), 400);
    };

    // Text to Speech
    speak(content, times);
  }

  function _playAttentionTone() {
    // 用 Web Audio 播放一个短促、较响的提示音，弥补 speechSynthesis 音量无法超过 1.0 的限制
    // 复用共享 AudioContext，避免每次 new 出的实例在后台被立即挂起
    try {
      const ctx = _ensureSharedAudioCtx();
      if (!ctx) return;
      if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, ctx.currentTime);
      gain.gain.setValueAtTime(0.0001, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(1.0, ctx.currentTime + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.35);
      osc.connect(gain).connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.4);
    } catch (_) {}
  }

  function speak(text, repeatCount = 1) {
    if (!window.speechSynthesis) return;
    // 确保静音保活音频和 AudioContext 处于播放/运行状态，
    // 即使 B 设备浏览器最小化或切到后台也能继续播报
    _ensureKeepAliveAudio();
    if (_sharedAudioCtx && _sharedAudioCtx.state === 'suspended') {
      try { _sharedAudioCtx.resume(); } catch (_) {}
    }
    try {
      if (window.speechSynthesis.paused) window.speechSynthesis.resume();
    } catch (_) {}
    window.speechSynthesis.cancel(); // Stop current speech
    const times = Math.max(1, parseInt(repeatCount, 10) || 1);
    // 播报前先播放提示音，抬升整体感知音量
    _playAttentionTone();
    for (let i = 0; i < times; i++) {
      const msg = new SpeechSynthesisUtterance(text);
      msg.lang = 'zh-CN';
      msg.rate = 1.0;
      msg.pitch = 1.0;
      msg.volume = 1.0; // Web Speech API 支持的最大音量
      window.speechSynthesis.speak(msg);
    }
  }

  async function shout(content, repeatCount = 1) {
    const token = Store.getToken();
    if (!token) return { ok: false, msg: '未登录' };
    let repeat = parseInt(repeatCount, 10) || 1;
    if (repeat < 1) repeat = 1;
    if (repeat > 20) repeat = 20;
    try {
      const res = await fetch(Store.API + '?action=sendAnnouncement', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, content, repeatCount: repeat })
      });
      return await res.json();
    } catch (e) {
      return { ok: false, msg: '网络请求失败' };
    }
  }

  function openShoutModal() {
    if (document.getElementById('ra-input-overlay')) return;

    const overlay = document.createElement('div');
    overlay.id = 'ra-input-overlay';
    overlay.className = 'ra-overlay';
    overlay.innerHTML = `
      <div class="ra-modal" style="padding: 25px;">
        <div class="ra-header" style="font-size: 1.3rem; margin-bottom: 15px;">📢 发送隔空喊话</div>
        <input type="text" id="ra-input-text" style="width: 100%; border: 2px solid #e2e8f0; padding: 12px 15px; border-radius: 12px; font-size: 1.05rem; margin-bottom: 14px; outline: none; transition: border 0.2s; box-sizing: border-box;" placeholder="请输入对教室喊话的内容..." autocomplete="off">
        <div style="display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 20px;">
          <label for="ra-input-repeat" style="font-size: 0.95rem; color: #334155; font-weight: 600;">语音循环次数</label>
          <div style="display: flex; align-items: center; gap: 6px;">
            <button type="button" id="ra-repeat-minus" style="width: 32px; height: 32px; border-radius: 8px; border: 1px solid #cbd5e1; background: #f8fafc; color: #334155; font-weight: 700; cursor: pointer;">−</button>
            <input type="number" id="ra-input-repeat" min="1" max="20" value="1" style="width: 60px; text-align: center; border: 2px solid #e2e8f0; padding: 6px 4px; border-radius: 8px; font-size: 1rem; outline: none;">
            <button type="button" id="ra-repeat-plus" style="width: 32px; height: 32px; border-radius: 8px; border: 1px solid #cbd5e1; background: #f8fafc; color: #334155; font-weight: 700; cursor: pointer;">+</button>
          </div>
        </div>
        <div style="display: flex; gap: 12px; justify-content: center;">
          <button class="ra-close" id="ra-input-cancel" style="background: #94a3b8; box-shadow: none; flex: 1;">取消</button>
          <button class="ra-close" id="ra-input-send" style="flex: 1;">发送</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);

    const input = document.getElementById('ra-input-text');
    input.focus();

    input.addEventListener('focus', () => input.style.borderColor = '#3b82f6');
    input.addEventListener('blur', () => input.style.borderColor = '#e2e8f0');

    const closeOverlay = () => {
      overlay.classList.add('fade-out');
      setTimeout(() => overlay.remove(), 400);
    };

    document.getElementById('ra-input-cancel').onclick = closeOverlay;

    const repeatInput = document.getElementById('ra-input-repeat');
    const clampRepeat = () => {
      let v = parseInt(repeatInput.value, 10);
      if (isNaN(v) || v < 1) v = 1;
      if (v > 20) v = 20;
      repeatInput.value = v;
      return v;
    };
    repeatInput.addEventListener('change', clampRepeat);
    repeatInput.addEventListener('blur', clampRepeat);
    document.getElementById('ra-repeat-minus').onclick = () => {
      repeatInput.value = Math.max(1, (parseInt(repeatInput.value, 10) || 1) - 1);
      clampRepeat();
    };
    document.getElementById('ra-repeat-plus').onclick = () => {
      repeatInput.value = Math.min(20, (parseInt(repeatInput.value, 10) || 1) + 1);
      clampRepeat();
    };

    const send = async () => {
      const text = input.value.trim();
      if (!text) {
        input.focus();
        return;
      }
      const times = clampRepeat();
      closeOverlay();

      try {
        const res = await shout(text, times);
        if (res.ok) {
          if (typeof UI !== 'undefined') UI.toast('📢 喊话已发送', 'success');
        } else {
          if (typeof UI !== 'undefined') UI.toast('❌ 发送失败：' + res.msg, 'error');
        }
      } catch (e) {
        console.error(e);
        if (typeof UI !== 'undefined') UI.toast('❌ 发生错误，请重试', 'error');
      }
    };

    document.getElementById('ra-input-send').onclick = send;
    input.onkeydown = (e) => {
      if (e.key === 'Enter') send();
      if (e.key === 'Escape') closeOverlay();
    };
  }

  function _injectStyles() {
    if (document.getElementById('ra-styles')) return;
    const style = document.createElement('style');
    style.id = 'ra-styles';
    style.textContent = `
      .ra-overlay {
        position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
        background: rgba(0,0,0,0.4); backdrop-filter: blur(8px);
        z-index: 200000; display: flex; align-items: center; justify-content: center;
        animation: ra-fade-in 0.4s ease-out;
      }
      .ra-modal {
        background: #ffffff; border-radius: 24px; width: 90%; max-width: 400px; padding: 30px;
        box-shadow: 0 30px 80px rgba(0,0,0,0.3); border: 2px solid #3b82f6;
        text-align: center; transform: scale(1); transition: 0.3s;
        box-sizing: border-box;
      }
      .ra-header { font-size: 1.5rem; font-weight: 900; color: #1e3a8a; margin-bottom: 20px; }
      .ra-body { font-size: 1.25rem; font-weight: 700; color: #334155; line-height: 1.6; margin-bottom: 25px; }
      .ra-close {
        background: #3b82f6; color: white; border: none; padding: 12px 30px;
        border-radius: 12px; font-weight: 800; cursor: pointer; font-size: 1rem;
        box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
      }
      .ra-overlay.fade-out { opacity: 0; pointer-events: none; }
      @keyframes ra-fade-in { from { opacity: 0; transform: scale(0.9); } to { opacity: 1; transform: scale(1); } }
    `;
    document.head.appendChild(style);
  }

  return { init, shout, speak, openShoutModal };
})();

