    `;
      document.head.appendChild(style);
    }

    _modalEl.innerHTML = `
      <div class="ac-v13-modal">
        <!-- Tree View (Left) -->
        <div class="ac-v13-left">
          <div class="ac-v13-growth-label">成长值: <span id="ac-v13-growth-val">0</span>%</div>
