          <!-- 顶部圆弧边缘的五角星装饰（较小） -->
          ${[200, 220, 240, 260, 280, 300, 320, 340].map(angle => {
            const rad = angle * Math.PI / 180;
            const distance = 135;
            const x = Math.cos(rad - Math.PI/2) * distance;
