css/style.css:
/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   DESIGN TOKENS
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
:root {
  /* Brand */
  --primary: #7c3aed;
  --primary-rgb: 124, 58, 237;
  --primary-light: #a78bfa;
  --primary-dark: #5b21b6;
  --primary-xdark: #3b0764;
  --secondary: #f59e0b;
  --secondary-light: #fcd34d;
  /* Semantic */
  --success: #10b981;
  --danger: #ef4444;
  --warning: #f97316;
  --info: #3b82f6;
  /* Surface */
  --bg: #f4f2ff;
  --bg-card: #ffffff;
  --glass: rgba(255, 255, 255, .72);
  --glass-border: rgba(255, 255, 255, .5);
  /* Text */
  --text: #18181b;
  --text-muted: #71717a;
  --text-light: #a1a1aa;
  /* Border */
  --border: #e4e4e7;
  --border-focus: rgba(var(--primary-rgb), .45);
  /* Shadows */
  --shadow-xs: 0 1px 3px rgba(0, 0, 0, .06), 0 1px 2px rgba(0, 0, 0, .04);
  --shadow-sm: 0 2px 8px rgba(var(--primary-rgb), .08), 0 1px 3px rgba(0, 0, 0, .05);
  --shadow: 0 4px 16px rgba(var(--primary-rgb), .10), 0 1px 4px rgba(0, 0, 0, .06);
  --shadow-md: 0 8px 28px rgba(var(--primary-rgb), .14), 0 2px 8px rgba(0, 0, 0, .07);
  --shadow-lg: 0 16px 48px rgba(var(--primary-rgb), .18), 0 4px 12px rgba(0, 0, 0, .08);
  --shadow-color: 0 4px 20px;
  /* Radii */
  --radius-xs: 6px;
  --radius-sm: 10px;
  --radius: 14px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  /* Motion */
  --transition: .18s cubic-bezier(.4, 0, .2, 1);
  --spring: .3s cubic-bezier(.34, 1.56, .64, 1);
}

/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   RESET
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei", "Helvetica Neue", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  overflow-x: hidden;
}

/* Subtle dot-grid background */
body::before {
  content: '';
  position: fixed;
  top:0;right:0;bottom:0;left:0;
  z-index: -1;
  background-image: radial-gradient(circle at 1px 1px, rgba(var(--primary-rgb), .08) 1px, transparent 0);
  background-size: 28px 28px;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

input,
select,
textarea {
  font-family: inherit;
  font-size: inherit;
  outline: none;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .5rem .85rem;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
  color: var(--text);
  background: #fff;
}

input:focus,
select:focus,
textarea:focus {
  border-color: var(--primary-light);
  box-shadow: 0 0 0 3.5px rgba(124, 58, 237, .15);
  background: #fdfcff;
}

a {
  color: var(--primary);
  text-decoration: none;
}

.hidden {
  display: none !important;
}

code {
  font-family: "JetBrains Mono", "Fira Code", "Consolas", monospace;
  background: rgba(124, 58, 237, .08);
  color: var(--primary-dark);
  border-radius: 4px;
  padding: .1em .35em;
  font-size: .88em;
}

/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   PAGES
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
.page {
  display: none;
  min-height: 100vh;
}

.page.active {
  display: block;
}

/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   BUTTON SYSTEM
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  background: linear-gradient(135deg, #8b5cf6, #7c3aed 50%, #6d28d9);
  color: #fff;
  padding: .6rem 1.4rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: .9rem;
  transition: all var(--transition);
  box-shadow: 0 2px 10px rgba(124, 58, 237, .35), inset 0 1px 0 rgba(255, 255, 255, .15);
  letter-spacing: .01em;
  position: relative;
  overflow: hidden;
}

.btn-primary::after {
  content: '';
  position: absolute;
  top:0;right:0;bottom:0;left:0;
  background: linear-gradient(135deg, rgba(255, 255, 255, .12), transparent);
  opacity: 0;
  transition: opacity var(--transition);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(124, 58, 237, .4);
}

.btn-primary:hover::after {
  opacity: 1;
}

.btn-primary:active {
  transform: translateY(0);
  box-shadow: 0 2px 8px rgba(124, 58, 237, .3);
}

.btn-block {
  width: 100%;
  padding: .8rem;
  font-size: 1rem;
  border-radius: var(--radius);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .3rem;
  background: var(--glass);
