.auth-bg {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #1e0533 0%, #3b0764 25%, #6d28d9 55%, #a855f7 80%, #f472b6 100%);
  position: relative;
  overflow: hidden;
}

/* Animated orbs */
.auth-bg::before,
.auth-bg::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  animation: orbFloat 8s ease-in-out infinite;
}

.auth-bg::before {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(168, 85, 247, .35) 0%, transparent 70%);
  top: -180px;
  right: -120px;
  animation-delay: 0s;
}

.auth-bg::after {
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(99, 102, 241, .3) 0%, transparent 70%);
  bottom: -150px;
  left: -80px;
  animation-delay: -4s;
}

@keyframes orbFloat {

  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }

  33% {
    transform: translate(30px, -20px) scale(1.05);
  }

  66% {
    transform: translate(-20px, 15px) scale(.97);
  }
}

/* Floating particles */
.auth-bg .auth-particles {
  position: absolute;
  top:0;right:0;bottom:0;left:0;
  overflow: hidden;
  pointer-events: none;
}

.auth-card {
  background: rgba(255, 255, 255, .96);
