  filter: drop-shadow(0 4px 12px rgba(124, 58, 237, .4));
}

@keyframes logoBounce {

  0%,
  100% {
    transform: translateY(0) scale(1);
  }

  50% {
    transform: translateY(-6px) scale(1.05);
  }
}

.logo-title {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -.01em;
