  animation-delay: 0s;
  font-size: 2.4rem;
}

.af2 {
  top: 15%;
  right: 10%;
  animation-duration: 9s;
  animation-delay: -2s;
  font-size: 1.8rem;
}

.af3 {
  top: 70%;
  left: 5%;
  animation-duration: 8s;
  animation-delay: -1s;
  font-size: 2.8rem;
}

.af4 {
  top: 80%;
  right: 8%;
  animation-duration: 6.5s;
  animation-delay: -3s;
  font-size: 2rem;
}

.af5 {
  top: 40%;
  left: 3%;
  animation-duration: 10s;
  animation-delay: -4s;
  font-size: 1.6rem;
}

.af6 {
  top: 55%;
  right: 4%;
  animation-duration: 7.5s;
  animation-delay: -1.5s;
  font-size: 2.2rem;
}

.af7 {
  top: 25%;
