  letter-spacing: -.01em;
}

/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   FILTER BAR
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
.filter-bar {
  display: flex;
  gap: .65rem;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 1.1rem;
  background: var(--bg-card);
  padding: .8rem 1.1rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  border: 1.5px solid var(--border);
}

.filter-input {
  min-width: 160px;
  font-size: .875rem;
}

.filter-select {
  font-size: .875rem;
  min-width: 115px;
}

.filter-score {
  display: flex;
  align-items: center;
  gap: .4rem;
}

.filter-input-sm {
  width: 82px;
  font-size: .875rem;
}

.batch-bar {
  display: flex;
  align-items: center;
  gap: .6rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
  background: var(--bg-card);
  padding: .5rem .85rem;
  border-radius: var(--radius);
  border: 1.5px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: border-color .2s;
}

.batch-bar.active {
  border-color: rgba(124, 58, 237, .45);
  background: linear-gradient(135deg, rgba(124, 58, 237, .04), rgba(168, 85, 247, .04));
}

/* 瑙﹀彂鎸夐挳 */
.batch-toggle-btn {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-weight: 600;
  font-size: .85rem;
  padding: .35rem .85rem !important;
  border: 1.5px solid var(--border) !important;
  border-radius: 20px !important;
  background: transparent;
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s;
  white-space: nowrap;
}

.batch-toggle-btn:hover {
  border-color: var(--primary) !important;
  color: var(--primary);
}

.batch-bar.active .batch-toggle-btn {
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
  color: #fff !important;
  border-color: transparent !important;
}

/* 灞曞紑鍐呭鍖猴細榛樿闅愯棌 */
.batch-expanded {
  display: none;
  align-items: center;
  gap: .55rem;
  flex-wrap: wrap;
}

.batch-bar.active .batch-expanded {
  display: flex;
}

/* 鍏ㄩ€夋寜閽?*/
.batch-select-btn {
  border: 1.5px dashed rgba(124, 58, 237, .5) !important;
  color: var(--primary) !important;
  background: transparent;
  font-weight: 600;
  transition: background .15s;
}

.batch-select-btn.all-selected {
  background: rgba(124, 58, 237, .1);
}

/* 璁℃暟 */
.batch-count-label {
  font-size: .83rem;
  color: var(--muted);
  min-width: 3.5rem;
}

.batch-count-label.has-selection {
  font-weight: 700;
  color: var(--primary);
}

/* 鍒嗗壊绾?*/
.batch-divider {
  width: 1px;
  height: 20px;
  background: var(--border);
  margin: 0 .1rem;
  flex-shrink: 0;
}

/* 绂佺敤鎬?*/
.batch-bar button:disabled {
  opacity: .35;
  cursor: not-allowed;
  pointer-events: none;
}

#batch-count {
  font-size: .875rem;
}

/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   STUDENTS GRID
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
.students-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--card-min-width, 198px), 1fr));
  gap: 1.25rem;
  transition: all 0.3s ease;
}

/* 紧凑模式：专门针对手机端优化为 3 列 */
.students-grid.grid-compact {
  grid-template-columns: repeat(3, 1fr) !important;
  gap: 0.5rem !important;
}

.grid-compact .student-card {
  border-radius: 12px;
  /* 保持高度比例，避免变瘦长 */
  display: flex;
  flex-direction: column;
}

.grid-compact .card-pet-wrap {
  height: 80px; /* 稍微调高一点，保持比例 */
}

.grid-compact .card-pet-img,
.grid-compact .sc2-adopt-egg {
  height: 85px !important;
  width: 85px !important;
}

.grid-compact .card-name {
  font-size: 0.8rem;
  margin-bottom: 0.1rem;
  padding: 0 0.3rem;
}

.grid-compact .card-level-badge {
  font-size: 0.55rem;
  padding: 0.1rem 0.35rem;
}

.grid-compact .card-progress-wrap {
  margin: 0 0.4rem 0.4rem;
}

.grid-compact .card-actions {
  padding: 0.25rem 0.3rem 0.4rem;
  gap: 0.25rem;
}

.grid-compact .ca-btn {
  height: 30px;
  font-size: 0.7rem;
}

.grid-compact .ca-btn .ri {
  font-size: 0.9rem;
}

/* 紧凑模式下隐藏次要信息以节省垂直空间 */
.grid-compact .card-medal-row,
.grid-compact .sc2-grouptag,
.grid-compact .card-student-no {
  display: none !important;
}

@media (max-width: 480px) {
  .students-grid.grid-compact {
    grid-template-columns: repeat(auto-fill, minmax(90px, 1fr));
  }
}

.students-empty {
  grid-column: 1/-1;
  text-align: center;
  padding: 5rem 1rem;
  color: var(--text-muted);
}

.students-empty .empty-icon {
  font-size: 4.5rem;
  display: block;
  margin-bottom: .85rem;
  opacity: .35;
}

/* 绌虹彮绾ф槑鏄惧叆鍙?*/
.students-empty-cta {
  padding: 4rem 1.5rem;
}

.students-empty-cta .empty-icon {
  font-size: 5rem;
  opacity: .5;
}

.students-empty-cta .empty-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: .4rem;
}

.students-empty-cta .empty-desc {
  font-size: .9rem;
  color: var(--text-muted);
  margin-bottom: 1.8rem;
  max-width: 320px;
  margin-left: auto;
  margin-right: auto;
}

.students-empty-cta .empty-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  justify-content: center;
  align-items: center;
}

.students-empty-cta .empty-cta-btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .6rem 1.25rem;
  font-size: .95rem;
  font-weight: 600;
}

.students-empty-cta .empty-cta-btn .ri {
  font-size: 1.15rem;
}

/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   STUDENT CARD  鈽?Core redesign
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
.student-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 0;
  box-shadow: var(--shadow-sm);
  border: 1.5px solid transparent;
  transition: transform var(--spring), box-shadow var(--transition), border-color var(--transition);
  position: relative;
  overflow: hidden;
  user-select: none;
  /* 性能优化：启用硬件加速并告知浏览器提前准备 */
  /* 现代浏览器优化：仅在视图内渲染布局 */
}

.student-card:hover {
  transform: translateY(-5px) scale(1.01);
  box-shadow: var(--shadow-md);
}

.student-card.selected {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(var(--primary-rgb), .2), var(--shadow-md);
}

.student-card.selected::after {
  content: '';
  /* cleared 鈥?using .card-select-check instead */
}

/* 鈹€鈹€ 鍗＄墖宸︿笂瑙掑嬀閫夋锛堥粯璁ら殣钘忥紝select-mode 鏃跺嚭鐜帮級鈹€鈹€ */
.card-select-check {
  position: absolute;
  top: .45rem;
  left: 3.8rem;
  z-index: 10;
  width: 22px;
  height: 22px;
  border: 2px solid rgba(var(--primary-rgb), .35);
  border-radius: 50%;
  background: rgba(255, 255, 255, .85);
  display: none;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color .18s, background .18s, transform .15s, box-shadow .15s;
  box-shadow: 0 1px 4px rgba(0, 0, 0, .08);
}

.select-mode .card-select-check {
  display: flex;
}

.card-select-check:hover {
  border-color: var(--primary);
  background: rgba(var(--primary-rgb), .08);
  transform: scale(1.15);
}

.card-check-icon {
  font-size: .68rem;
  font-weight: 800;
  color: transparent;
  line-height: 1;
}

.student-card.selected .card-select-check {
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
  border-color: var(--primary);
  box-shadow: 0 2px 8px rgba(var(--primary-rgb), .4);
}

.student-card.selected .card-check-icon {
  color: #fff;
}

/* Card top gradient banner (group color stripe upgraded) */
.card-group-stripe {
  height: 5px;
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

/* default gradient if no group */
.card-group-stripe:not([style]) {
  background: linear-gradient(90deg, #8b5cf6, #a78bfa, #c4b5fd);
}

/* Pet area */
.card-pet-wrap {
  position: relative;
  height: 108px;
  display: flex;
  align-items: center;
  justify-content: center;
  /* soft radial glow behind pet */
  background: radial-gradient(ellipse 80% 70% at 50% 60%, rgba(var(--primary-rgb), .07) 0%, transparent 80%);
  /* 性能优化：添加透视感，辅助 GPU 精确计算位移 */
}

.card-pet-img {
  height: 110px;
  width: 110px;
  object-fit: contain;
  animation: petFloat 3.5s ease-in-out infinite;
  /* 抖动修复：移除 pixelated，因为它会强制像素对齐导致位移不连贯 */
  image-rendering: auto; 
  filter: drop-shadow(0 6px 12px rgba(0, 0, 0, .18));
  position: relative;
  z-index: 1;
  /* 极致顺滑：强制开启 GPU 图层并消除背面闪烁 */
}

@keyframes petFloat {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

.card-pet-missing {
  width: 90px;
  height: 90px;
  background: linear-gradient(135deg, #f3f4f6, #e5e7eb);
  border-radius: var(--radius);
  font-size: 2.8rem;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: petFloat 3s ease-in-out infinite;
}

/* Level badge */
.card-level-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .3rem;
  margin-bottom: .45rem;
  padding: 0 .75rem;
}

.card-level-badge {
  background: linear-gradient(135deg, #f59e0b, #ef4444);
  color: #fff;
  font-size: .68rem;
  font-weight: 800;
  padding: .18rem .55rem;
  border-radius: 20px;
  box-shadow: 0 2px 6px rgba(245, 158, 11, .35);
  letter-spacing: .03em;
}

.card-level-title {
  font-size: .68rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* Name */
.card-name {
  text-align: center;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -.01em;
  margin-bottom: .15rem;
  padding: 0 .75rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card-student-no {
  text-align: center;
  font-size: .72rem;
  color: var(--text-light);
  margin-bottom: .5rem;
}

/* Progress */
.card-progress-wrap {
  margin: 0 .85rem .6rem;
}

.card-progress-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: .7rem;
  color: var(--text-muted);
  margin-bottom: .25rem;
  font-weight: 500;
}

/* "杩樺樊 XX 馃崡" 鈥?matches card-chicken-val style */
.card-need-num {
  font-weight: 800;
  font-size: .82rem;
  background: linear-gradient(135deg, #f59e0b, #f97316);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin: 0 .15rem;
}

.card-need-leg {
  font-size: .82rem;
  /* keep emoji rendering natural but shift baseline to align */
  vertical-align: middle;
  line-height: 1;
}

.card-maxlevel {
  font-size: .72rem;
  font-weight: 700;
  background: linear-gradient(135deg, #f59e0b, #f97316);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.card-progress-bar {
  height: 5px;
  background: #f0f0f8;
  border-radius: 3px;
  overflow: hidden;
}

.card-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #8b5cf6, #a78bfa, #c4b5fd);
  border-radius: 3px;
  transition: width .6s cubic-bezier(.34, 1.56, .64, 1);
  position: relative;
}

.card-progress-fill::after {
  content: '';
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  height: 8px;
  background: #fff;
  border: 2px solid #8b5cf6;
  border-radius: 50%;
}

/* Progress sub-label */
.card-progress-sub {
  font-size: .66rem;
  color: var(--text-light);
  text-align: right;
  margin-top: .2rem;
  letter-spacing: .01em;
}

/* Score chips */
.card-scores {
  display: flex;
  justify-content: center;
  gap: .5rem;
  margin: 0 .75rem .75rem;
}

.card-score-item {
  flex: 1;
  text-align: center;
  padding: .4rem .5rem;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, rgba(124, 58, 237, .06), rgba(168, 85, 247, .04));
  border: 1px solid rgba(124, 58, 237, .1);
}

.card-score-val {
  font-size: .95rem;
  font-weight: 800;
  line-height: 1;
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.card-score-label {
  font-size: .65rem;
  color: var(--text-muted);
  margin-top: .15rem;
}

.card-chicken-val {
  font-size: .95rem;
  font-weight: 800;
  line-height: 1;
  background: linear-gradient(135deg, #f59e0b, #f97316);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* 楦¤吙涓嶈冻鏃跺彉鐏拌鍛?*/
.card-score-item--empty .card-chicken-val {
  background: linear-gradient(135deg, #9ca3af, #6b7280);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.card-score-item--empty {
  background: rgba(239, 68, 68, .05) !important;
  border-color: rgba(239, 68, 68, .15) !important;
}

.card-score-item--empty .card-score-label {
  color: var(--danger);
  font-weight: 600;
}

/* Medal strip */
.card-medals {
  display: flex;
  align-items: center;
  gap: .22rem;
  padding: .45rem .85rem .35rem;
  min-height: 34px;
  border-top: 1px solid rgba(124, 58, 237, .07);
  flex-wrap: wrap;
}

.card-medals-empty {
  justify-content: center;
  font-size: .68rem;
  color: var(--text-light);
  font-style: italic;
}

.card-medal-icon {
  font-size: 1.15rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(245, 158, 11, .12), rgba(249, 115, 22, .1));
  border: 1px solid rgba(245, 158, 11, .25);
  cursor: default;
  transition: transform var(--spring);
  line-height: 1;
}

.card-medal-icon:hover {
  transform: scale(1.25) rotate(-8deg);
  z-index: 2;
  position: relative;
}

.card-medal-more {
  font-size: .7rem;
  font-weight: 800;
  color: var(--secondary);
  background: rgba(245, 158, 11, .12);
  border: 1px solid rgba(245, 158, 11, .25);
  border-radius: 20px;
  padding: .1rem .45rem;
  white-space: nowrap;
}

/* Action buttons */
.card-actions {
  display: flex;
  gap: .3rem;
  padding: 0 .75rem .85rem;
  justify-content: center;
}

.card-action-btn {
  flex: 1;
  padding: .42rem .2rem;
  border-radius: var(--radius-sm);
  font-size: .78rem;
  font-weight: 700;
  text-align: center;
  transition: all var(--transition);
  border: 1.5px solid var(--border);
  color: var(--text-muted);
  background: #fafafa;
}

.card-action-btn:hover {
  transform: scale(1.06) translateY(-1px);
}

.card-action-btn.add {
  color: #fff;
  background: linear-gradient(135deg, #34d399, #10b981);
  border-color: transparent;
  box-shadow: 0 2px 6px rgba(16, 185, 129, .3);
}

.card-action-btn.add:hover {
  box-shadow: 0 4px 12px rgba(16, 185, 129, .4);
}

.card-action-btn.deduct {
  color: #fff;
  background: linear-gradient(135deg, #f87171, #ef4444);
  border-color: transparent;
  box-shadow: 0 2px 6px rgba(239, 68, 68, .3);
}

.card-action-btn.deduct:hover {
  box-shadow: 0 4px 12px rgba(239, 68, 68, .4);
}

.card-action-btn.feed {
  color: #fff;
  background: linear-gradient(135deg, #fbbf24, #f97316);
  border-color: transparent;
  box-shadow: 0 2px 6px rgba(249, 115, 22, .3);
}

.card-action-btn.feed:hover {
  box-shadow: 0 4px 12px rgba(249, 115, 22, .4);
}

.card-action-btn.more {
  background: linear-gradient(135deg, rgba(124, 58, 237, .1), rgba(168, 85, 247, .1));
  color: var(--primary);
  border-color: rgba(124, 58, 237, .2);
  position: relative;
}

.card-action-btn.more:hover {
  background: var(--primary);
  color: #fff;
}

/* 鈹€鈹€ 榻胯疆鎿嶄綔寮规鑿滃崟 鈹€鈹€ */
.ca-more-wrap {
  position: relative;
}

.card-action-menu {
  display: flex;
  flex-direction: column;
  gap: .3rem;
  padding: .25rem 0 .5rem;
}

.cam-item {
  display: flex;
  align-items: center;
  gap: .85rem;
  width: 100%;
  padding: .72rem 1.1rem;
  background: none;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  text-align: left;
  transition: background .14s, transform .1s;
}

.cam-item:hover {
  background: rgba(124, 58, 237, .07);
  transform: translateX(3px);
}

.cam-item:hover .cam-label {
  color: var(--primary);
}

.cam-icon {
  font-size: 1.35rem;
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-soft);
  border-radius: 8px;
  flex-shrink: 0;
}

.cam-label {
  font-size: .9rem;
  font-weight: 600;
  color: var(--text);
  line-height: 1.2;
  transition: color .14s;
}

.cam-sub {
