  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: -.01em;
}

.modal-close {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .95rem;
  color: var(--text-muted);
  transition: all var(--transition);
  background: transparent;
}

.modal-close:hover {
  background: rgba(239, 68, 68, .1);
  color: var(--danger);
  transform: rotate(90deg);
}

.modal-body {
  padding: 1.35rem 1.6rem 1.6rem;
  overflow-y: auto;
