.rc-overlay {
  background: radial-gradient(ellipse at center, #1a0533 0%, #0a011a 70%);
  align-items: center;
  justify-content: center;
}

.rc-content {
  text-align: center;
  padding: 2rem 1rem;
}

.rc-title {
  font-size: 2.2rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 2.5rem;
  background: linear-gradient(135deg, #c4b5fd, #f9a8d4);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  filter: none;
}

.rc-drum {
  width: 230px;
  height: 230px;
  margin: 0 auto 2.5rem;
  background: rgba(255, 255, 255, .04);
  border-radius: 50%;
  border: 2px solid rgba(168, 85, 247, .4);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  box-shadow: 0 0 0 8px rgba(168, 85, 247, .08), 0 0 0 16px rgba(168, 85, 247, .04),
    0 0 80px rgba(168, 85, 247, .3);
}

.rc-drum::before {
  content: '';
  position: absolute;
  top:-10px;right:-10px;bottom:-10px;left:-10px;
  border-radius: 50%;
  border: 1px dashed rgba(168, 85, 247, .25);
  animation: drumRotate 12s linear infinite;
}

@keyframes drumRotate {
  to {
    transform: rotate(360deg);
  }
}

.rc-pet-wrap {
  text-align: center;
}

.rc-pet-img {
  width: 120px;
  height: 120px;
  object-fit: contain;
  filter: drop-shadow(0 0 24px rgba(168, 85, 247, .9));
}

.rc-name {
  font-size: 1.5rem;
  font-weight: 800;
  color: #fff;
  margin-top: .6rem;
  text-shadow: 0 0 24px rgba(255, 255, 255, .5);
}

.rc-drum.spinning .rc-pet-wrap {
  animation: rcSpin .08s linear infinite;
}

@keyframes rcSpin {
  0% {
    transform: scale(.95) rotate(-3deg);
    opacity: .7;
  }

  50% {
    transform: scale(1.06) rotate(3deg);
    opacity: 1;
  }

  100% {
    transform: scale(.95) rotate(-3deg);
    opacity: .7;
  }
}

.rc-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

.rc-result {
  margin-top: 1.75rem;
  font-size: 1.25rem;
  color: #fcd34d;
  font-weight: 700;
  min-height: 2rem;
  letter-spacing: .02em;
}

