}

/* Excel upload */
.excel-upload-area {
  border: 2px dashed rgba(124, 58, 237, .3);
  border-radius: var(--radius);
  padding: 2rem 1.5rem;
  text-align: center;
  transition: all var(--transition);
  cursor: pointer;
  background: linear-gradient(135deg, rgba(124, 58, 237, .03), rgba(168, 85, 247, .03));
  margin-bottom: .85rem;
}

.excel-upload-area:hover,
.excel-upload-area.drag-over {
  border-color: var(--primary);
  background: rgba(124, 58, 237, .07);
  transform: scale(1.01);
}

.excel-upload-icon {
  font-size: 2.8rem;
  margin-bottom: .6rem;
}

.excel-upload-area p {
  color: var(--text-muted);
  font-size: .875rem;
  margin-bottom: .2rem;
}

.batch-template-hint {
  display: flex;
  align-items: center;
  gap: .85rem;
  padding: .65rem .9rem;
  background: linear-gradient(135deg, rgba(245, 158, 11, .07), rgba(249, 115, 22, .05));
