  background: #f9f9fc;
  cursor: pointer;
  font-size: .875rem;
  font-weight: 700;
  color: var(--text-muted);
}

.import-guide-icon {
  font-size: 1rem;
}

.guide-toggle {
  margin-left: auto;
  font-size: .78rem;
  color: var(--primary);
  font-weight: 600;
  padding: .15rem .5rem;
  border-radius: 4px;
  transition: background var(--transition);
}

.guide-toggle:hover {
  background: rgba(124, 58, 237, .1);
}

.import-guide-body {
  padding: .9rem;
