.flh-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 1.5rem;
  padding: 0.5rem 0;
}

.flh-sticker {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  border-radius: 16px;
  outline: none;
  transition: box-shadow 0.15s ease, transform 0.15s ease;
}

.flh-sticker:focus-visible {
