.class-nav-oval {
  background: rgba(255, 255, 255, .98);
  border-bottom: 1px solid var(--border);
  box-shadow: 0 1px 0 var(--border), 0 2px 14px rgba(0, 0, 0, .06);
  backdrop-filter: blur(16px);
