}

/* 鍗＄墖鍖哄煙鍐呯殑 gfbar锛氬乏瀵归綈銆佹棤鑳屾櫙鏉°€佹斁鍗＄墖涓婃柟 */
.gfbar-in-cards {
  background: none;
  border-bottom: none;
  padding: 0 0 .85rem 0;
  margin-bottom: .5rem;
}

@media (min-width: 1024px) {
  .gfbar-in-cards {
    padding: 0 0 1rem 0;
    margin-bottom: .75rem;
  }
}

/* 手机端专用：小组下方的显眼快捷按钮（隔空喊话、批量操作） */
.mob-action-bar {
  display: none; /* 默认隐藏，仅在手机端显示 */
  padding: 0 1rem 0.85rem;
  gap: 0.85rem;
  margin-top: -0.2rem;
  margin-bottom: 0.4rem;
}

@media (max-width: 768px) {
  .mob-action-bar {
    display: flex;
    justify-content: space-between;
  }
  
  /* 隐藏顶部导航中重复的按钮，实现“移到”下方的效果 */
  #nav-shout-btn {
    display: none !important;
  }
}

.mob-action-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  background: #ffffff;
  border: 1.5px solid #e2e8f0;
  border-radius: 16px; /* 更加圆润，显眼 */
  height: 52px; /* 增加高度，更易点击 */
  font-size: 1.05rem;
  font-weight: 700;
  color: #475569; /* 稍微深一点的灰色，增加对比度 */
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.04);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  outline: none;
  -webkit-tap-highlight-color: transparent;
}

.mob-action-btn:active {
  transform: scale(0.96);
  background: #f8fafc;
  border-color: var(--primary-light);
  color: var(--primary);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.02);
}

.mob-action-btn i {
  font-size: 1.45rem; /* 图标放大 */
  color: #64748b;
  transition: color 0.2s;
}

.mob-action-btn:active i {
  color: var(--primary);
}

.mob-action-btn span {
  white-space: nowrap;
}

.gfbar::-webkit-scrollbar {
  display: none;
}

.gfpill {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  padding: .28rem .8rem;
  border-radius: 20px;
  border: 1.5px solid var(--border);
  background: #fff;
