}

.gfpill-count {
  font-size: .7rem;
  opacity: .8;
}

.gfbar-spacer {
  flex: 1;
  min-width: .5rem;
}

.gfbar-btn {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  flex-shrink: 0;
  padding: .35rem .75rem;
  border-radius: 20px;
  font-size: .78rem;
  font-weight: 600;
  border: 1.5px solid var(--border);
  background: #fff;
  cursor: pointer;
  transition: all var(--transition);
