  background: rgba(245, 158, 11, .08);
}

.gfbar-screen-lock:hover {
  border-color: #7c3aed;
  color: #7c3aed;
  background: rgba(124, 58, 237, .09);
}

/* 鎺掑簭涓嬫媺 - 鎸傝浇鍒?body锛宖ixed 瀹氫綅纭繚娴簬鍗＄墖涔嬩笂 */
.sort-dropdown.sort-dropdown-fixed {
  position: absolute;
  min-width: 180px;
  padding: .5rem 0;
  background: #fff;
  border-radius: 12px;
