}

/* 鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?   SC2 STUDENT CARD  (new card design)
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
.sc2.student-card {
  position: relative;
  background: #fff;
  border-radius: 14px;
  border: 1.5px solid rgba(var(--primary-rgb), 0.40);
  box-shadow: 0 2px 10px rgba(0, 0, 0, .06),
    0 0 24px rgba(var(--primary-rgb), 0.28),
    0 4px 16px -2px rgba(var(--primary-rgb), 0.18),
    0 14px 48px -6px rgba(var(--primary-rgb), 0.42),
    0 20px 56px -10px rgba(var(--primary-rgb), 0.30);
  padding: 0;
  overflow: hidden;
  transition: transform var(--spring), box-shadow var(--transition), border-color var(--transition);
}

.sc2--hunger-gray {
  filter: grayscale(100%);
}

.is-dead .sc2-hunger-overlay {
  background: rgba(0, 0, 0, 0.25);
  pointer-events: auto; /* 核心：拦截底层点击 */
}

.sc2-top,
.sc2-check {
  position: relative;
  z-index: 11; /* 穿透浮层，保持可点 */
}

.sc2-hunger-overlay {
  position: absolute;
  top:0;right:0;bottom:0;left:0;
  z-index: 10;
  background: rgba(0, 0, 0, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.sc2-hunger-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.8rem;
  pointer-events: auto; /* 允许点击内部按钮 */
}



.sc2-hunger-msg {
  background: rgba(255, 255, 255, 0.96);
  padding: 0.5rem 1.2rem;
  border-radius: 99px;
  font-size: 1.2rem;
  font-weight: 900;
  color: #333;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
  border: 2px solid #fff;
  animation: hunger-pop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
  white-space: nowrap;
}

.is-critical .sc2-hunger-msg {
  color: #e11d48;
  animation: hunger-pop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), pulse-red-bg 2s infinite;
}

.is-dead .sc2-hunger-msg {
  background: #374151;
  color: #fff;
  border-color: #4b5563;
}

.sc2-readopt-btn {
  background: var(--primary, #3b82f6);
  color: #fff;
  border: none;
  padding: 0.5rem 1.2rem;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.2s;
  box-shadow: 0 4px 15px rgba(59, 130, 246, 0.4);
  animation: hunger-pop 0.5s 0.2s backwards;
}

.sc2-readopt-btn:hover {
  background: var(--secondary, #f59e0b);
  transform: translateY(-2px) scale(1.05);
  box-shadow: 0 6px 20px rgba(245, 158, 11, 0.4);
}

@keyframes hunger-pop {
  0% {
    transform: scale(0.5);
    opacity: 0;
  }

  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes pulse-red-bg {
  0% {
    box-shadow: 0 0 0 0 rgba(225, 29, 72, 0.4);
  }

  70% {
    box-shadow: 0 0 0 15px rgba(225, 29, 72, 0);
  }

  100% {
    box-shadow: 0 0 0 0 rgba(225, 29, 72, 0);
  }
}

.sc2.student-card:hover {
  transform: translateY(-4px) scale(1.01);
  border-color: rgba(var(--primary-rgb), 0.55);
  box-shadow: 0 8px 28px rgba(0, 0, 0, .1),
    0 0 32px rgba(var(--primary-rgb), 0.42),
    0 0 48px rgba(var(--primary-rgb), 0.22),
    0 18px 56px -6px rgba(var(--primary-rgb), 0.48),
    0 24px 64px -10px rgba(var(--primary-rgb), 0.35);
}

.sc2.student-card::before {
  display: none;
}

.sc2.student-card.selected {
  border-color: rgba(var(--primary-rgb), 0.65);
  box-shadow: 0 0 0 2px rgba(var(--primary-rgb), 0.30),
    0 0 20px rgba(var(--primary-rgb), 0.35),
    0 10px 24px -4px rgba(var(--primary-rgb), 0.28);
}

/* top row锛氱瓑绾?+ 鏇村 */
/* top row：等级 + 更多 */
.sc2-top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: .05rem .75rem;
  z-index: 12;
  pointer-events: none;
}

.sc2-top > * {
