  background: none;
  border: none;
  box-shadow: none;
  color: var(--text-muted);
  font-size: 1.1rem;
  font-weight: 900;
  cursor: pointer;
  padding: .2rem;
  margin: 0;
  transition: color .2s, transform .2s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.sc2-top .sc2-btn-more:hover {
