}

/* 婊＄骇锛氳悓瀹犲浘 + 鍙敜绁炲吔 */
.sc2-pet-max {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 0;
  width: 100%;
}

.sc2-pet-max {
  min-height: 175px;
  height: auto;
  padding: 0 0.45rem 0.2rem;
}


/* 棰嗗吇鍖哄煙锛堝彫鍞ょ鍏藉悗鏄剧ず铔?鐐瑰嚮棰嗗吇锛夆€?鐣ュ楂樺疇鐗╁尯浠ヤ究妗嗘洿澶?*/
.sc2-adopt-wrap {
  min-height: 195px;
  height: auto;
  padding: 1.8rem 0.45rem 2px;
}

.sc2-adopt-wrap {
  box-sizing: border-box;
  width: calc(100% - 0.35rem);
  max-width: 100%;
  min-height: 128px;
  height: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: 2px dashed var(--border);
