}

.sc2-prog-bar {
  height: 5px;
  background: #f0f0f5;
  border-radius: 3px;
  overflow: hidden;
}

.sc2-prog-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--gc, var(--primary)), #a98bf5);
  border-radius: 3px;
  transition: width .6s cubic-bezier(.34, 1.56, .64, 1);
  position: relative;
}

.sc2-prog-fill::before {
  content: '';
  position: absolute;
  top:0;right:0;bottom:0;left:0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .55), transparent);
