/* ══ GROUP RANK ══ */
.gr-overlay {
  background: rgba(8, 4, 22, .95);
  backdrop-filter: blur(12px);
  flex-direction: column;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s ease;
}

.gr-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.gr-list {
  padding-bottom: 2rem;
}

.gr-row {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: .9rem 1.5rem;
