.screen-lock-overlay {
  position: fixed;
  top:0;right:0;bottom:0;left:0;
  z-index: 200000;
  background: rgba(15, 10, 35, .74);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.screen-lock-overlay.open {
  display: flex;
}

/* 锁屏拦截层：允许浏览但拦截所有交互 */
.screen-lock-guard {
  position: fixed;
  top: 0; right: 0; bottom: 0; left: 0;
  z-index: 199000;
  background: transparent;
  cursor: not-allowed;
  display: none;
}

body.screen-lock-on .screen-lock-guard {
  display: block;
}

/* 锁屏时顶部提示条 */
.screen-lock-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 199500;
  padding: .5rem 1rem;
  background: linear-gradient(90deg, rgba(255, 89, 148, .95), rgba(124, 92, 255, .95));
  color: #fff;
  font-size: .88rem;
  font-weight: 600;
  text-align: center;
  display: none;
  box-shadow: 0 4px 14px rgba(0, 0, 0, .25);
  pointer-events: none;
}

body.screen-lock-on .screen-lock-bar {
  display: block;
}

/* 锁屏时保留原生滚动 */
body.screen-lock-on {
  overflow: auto;
}

/* 锁屏关闭按钮 */
.screen-lock-close {
  position: absolute;
  top: .5rem;
  right: .75rem;
  width: 2rem;
  height: 2rem;
  border: none;
  background: transparent;
  font-size: 1.4rem;
  line-height: 1;
  color: var(--text-muted);
