}

.screen-lock-icon {
  font-size: 2.5rem;
  line-height: 1;
  margin-bottom: .4rem;
}

.screen-lock-title {
  margin: 0 0 .35rem;
  font-size: 1.22rem;
  font-weight: 800;
  color: var(--text);
}

.screen-lock-sub {
  margin: 0 0 1rem;
  font-size: .87rem;
  color: var(--text-muted);
}

.screen-lock-input {
  width: 100%;
  margin-bottom: .85rem;
