/* ═══════════════════════ HOMEWORK STATS ═══════════════════════ */
.hw-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, .5);
  backdrop-filter: blur(8px);
  z-index: 10000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  animation: fadeIn .2s ease;
}

.hw-overlay.open {
  display: flex;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.hw-container {
  position: relative;
  width: 100%;
  max-width: 1400px;
  max-height: 90vh;
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: slideUp .3s cubic-bezier(.34, 1.56, .64, 1);
}

@keyframes slideUp {
  from { 
    opacity: 0;
    transform: translateY(30px) scale(.95);
  }
  to { 
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.hw-header {
  padding: 1.5rem 2rem;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, #f8f9ff 0%, #fff 100%);
}

.hw-header h2 {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

.hw-header-actions {
  display: flex;
  align-items: center;
  gap: .75rem;
}

.hw-task-switch-btn {
  padding: .5rem 1rem;
  border: none;
  border-radius: 999px;
  background: var(--primary);
  color: white;
  font-size: .85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  display: flex;
  align-items: center;
  gap: .35rem;
}

.hw-task-switch-btn:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(var(--primary-rgb), .3);
}

.hw-task-selector {
  padding: 1.5rem 2rem;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  animation: slideDown .2s ease;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hw-task-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: .75rem;
  margin-bottom: 1rem;
}

.hw-task-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: .75rem 1rem;
  background: white;
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
}

.hw-task-item:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.hw-task-item.active {
  border-color: var(--primary);
  background: rgba(var(--primary-rgb), .05);
}

.hw-task-item-name {
  font-size: .9rem;
  font-weight: 500;
  color: var(--text);
  flex: 1;
}

.hw-task-item-actions {
  display: flex;
  gap: .25rem;
  opacity: 0;
  transition: opacity var(--transition);
}

.hw-task-item:hover .hw-task-item-actions {
  opacity: 1;
}

.hw-task-item-btn {
  width: 24px;
  height: 24px;
  border: none;
  background: none;
  color: var(--text-muted);
  cursor: pointer;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .75rem;
  transition: all var(--transition);
}

.hw-task-item-btn:hover {
  background: var(--bg);
  color: var(--text);
}

.hw-task-item-btn.delete:hover {
  background: var(--danger);
  color: white;
}

.hw-task-actions {
  display: flex;
  justify-content: center;
}

.hw-task-add-btn {
  padding: .65rem 1.5rem;
  border: 2px dashed var(--border);
  background: white;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-size: .85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
}

.hw-task-add-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(var(--primary-rgb), .05);
