  border: none;
  border-radius: 999px;
  background: #f97316;
  color: white;
  font-size: .85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  display: flex;
  align-items: center;
  gap: .4rem;
}

.hw-reset-all-btn:hover {
