   Featuring: Glassmorphism, Modern Slider, Grid Cards
鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺愨晲鈺?*/
.pg-overlay {
  background: rgba(15, 10, 30, 0.85);
  backdrop-filter: blur(25px) saturate(180%);
  z-index: 2000;
  display: none;
  flex-direction: column;
}

.pg-overlay.open {
  display: flex;
  animation: pgFadeIn .4s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes pgFadeIn {
  from {
    opacity: 0;
    backdrop-filter: blur(0);
  }

  to {
    opacity: 1;
    backdrop-filter: blur(25px);
  }
}

.pg-header {
  padding: 0.4rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

.pg-title-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.pg-icon {
  font-size: 1.1rem;
  filter: drop-shadow(0 0 6px var(--primary));
}

.pg-title {
  color: #fff;
  font-size: 1.1rem;
  font-weight: 800;
  margin: 0;
}

.pg-subtitle {
  color: rgba(255, 255, 255, 0.4);
  font-size: 0.75rem;
  font-weight: 500;
}

.pg-header-right {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.pg-search-wrap {
  position: relative;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 99px;
  padding: 0.35rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  transition: all 0.3s ease;
}

.pg-search-wrap:focus-within {
  background: rgba(255, 255, 255, 0.15);
  border-color: var(--primary-light);
  box-shadow: 0 0 15px rgba(124, 58, 237, 0.03);
}

.pg-search-icon {
  font-size: 1rem;
  opacity: 0.6;
  color: #fff;
}

.pg-search-input {
  background: transparent;
  border: none;
  color: #fff;
  font-size: 0.9rem;
  width: 200px;
  padding: 0;
}

.pg-search-input::placeholder {
  color: rgba(255, 255, 255, 0.3);
}

.pg-close {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  padding: 0.4rem 1rem;
  border-radius: 99px;
  font-weight: 700;
  font-size: 0.8rem;
  border: 1px solid rgba(239, 68, 68, 0.2);
  transition: all 0.3s ease;
}

.pg-close:hover {
  background: #ef4444;
  color: #fff;
  transform: scale(1.05);
}

/* --- Level Slider Bar --- */
.pg-slider-bar {
  padding: 0.4rem 2rem;
  background: rgba(0, 0, 0, 0.12);
  display: flex;
  align-items: center;
  gap: 2rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.pg-lv-info {
  display: flex;
  flex-direction: column;
  min-width: 100px;
}

.pg-lv-num {
  font-size: 1.2rem;
  font-weight: 900;
  color: var(--primary-light);
  line-height: 1;
}

.pg-lv-title-text {
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.6);
  font-weight: 600;
  margin-top: 0.2rem;
}

.pg-slider-wrap {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 1rem;
  max-width: 600px;
}

.pg-slider-label {
  color: rgba(255, 255, 255, 0.4);
  font-size: 0.75rem;
  font-weight: 800;
  font-family: monospace;
}

/* Custom Range Input */
.pg-slider {
  -webkit-appearance: none;
  flex: 1;
  height: 8px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 99px;
  outline: none;
  position: relative;
  --pg-pct: 0%;
}

.pg-slider::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: var(--pg-pct);
  background: linear-gradient(90deg, var(--primary), var(--primary-light));
  border-radius: 99px;
  box-shadow: 0 0 10px rgba(124, 58, 237, 0.05);
}

.pg-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 24px;
  height: 24px;
  background: #fff;
  border: 4px solid var(--primary);
  border-radius: 50%;
  cursor: pointer;
  position: relative;
  z-index: 2;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.3);
  transition: transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.pg-slider::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.pg-lv-dots {
  display: flex;
  gap: 0.5rem;
}

.pg-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
  cursor: pointer;
  transition: all 0.3s ease;
}

.pg-dot:hover {
  background: rgba(255, 255, 255, 0.4);
  transform: scale(1.2);
}

.pg-dot.active {
  background: var(--primary-light);
  box-shadow: 0 0 10px var(--primary-light);
  transform: scale(1.3);
}

/* --- Body & Cards --- */
.pg-body {
  flex: 1;
  overflow-y: auto;
  padding: 2.5rem;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 2rem;
  align-content: start;
}

/* Scrollbar */
.pg-body::-webkit-scrollbar {
  width: 8px;
}

.pg-body::-webkit-scrollbar-track {
  background: transparent;
}

.pg-body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 10px;
}

.pg-body::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.2);
}

.pg-card {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  padding: 1.5rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
  cursor: pointer;
  position: relative;
  min-height: 200px;
  justify-content: center;
}

.pg-card:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(124, 58, 237, 0.04);
  transform: translateY(-8px);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
}

.pg-card::before {
  content: "";
  position: absolute;
  top:0;right:0;bottom:0;left:0;
  background: radial-gradient(circle at 50% 50%, rgba(124, 58, 237, 0.15), transparent 70%);
  opacity: 0;
  transition: opacity 0.4s ease;
}

.pg-card:hover::before {
  opacity: 1;
}

.pg-card-img-wrap {
  width: 140px;
  height: 140px;
  position: relative;
  margin-bottom: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  /* 性能优化：支持 3D 顺滑动画 */
}

.pg-card-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 8px 15px rgba(0, 0, 0, 0.3));
  z-index: 1;
}

.pg-card-lv-badge {
  position: absolute;
  top: -5px;
  right: -5px;
  background: linear-gradient(135deg, #f59e0b, #ef4444);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 800;
  padding: 0.2rem 0.6rem;
  border-radius: 99px;
  box-shadow: 0 4px 10px rgba(239, 68, 68, 0.4);
  z-index: 2;
}

.pg-card-info {
  text-align: center;
  z-index: 1;
}

.pg-card-name {
  color: #fff;
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 0.2rem;
}

.pg-card-title {
  color: rgba(255, 255, 255, 0.4);
  font-size: 0.75rem;
  font-weight: 500;
}

.pg-empty {
  grid-column: 1/-1;
  text-align: center;
  padding: 10rem 0;
  color: rgba(255, 255, 255, 0.3);
  font-size: 1.2rem;
}

/* Detail Modal Styles (override for premium look) */
.pg-detail-header {
  display: flex;
  align-items: center;
  gap: 1.2rem;
  margin-bottom: 2rem;
}

.pg-detail-emoji {
  font-size: 3rem;
}

.pg-detail-name {
  font-size: 1.8rem;
  font-weight: 900;
  color: var(--text);
  line-height: 1;
}

.pg-detail-sub {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 0.3rem;
}

.pg-detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 1rem;
}

.pg-detail-cell {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  transition: all 0.3s ease;
}

.pg-detail-cell--active {
  background: #f5f3ff;
  border-color: var(--primary-light);
  box-shadow: 0 8px 20px rgba(var(--primary-rgb), 0.01);
}

.pg-detail-lv-badge {
  position: absolute;
  top: 0.6rem;
  right: 0.6rem;
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--text-muted);
  background: #e2e8f0;
  padding: 0.15rem 0.5rem;
  border-radius: 99px;
}

.pg-detail-lv-badge.active {
  background: var(--primary);
  color: #fff;
}

.pg-detail-img {
  width: 100px;
  height: 100px;
  object-fit: contain;
  margin-bottom: 0.8rem;
  cursor: pointer;
  transition: transform 0.2s ease;
}

.pg-detail-img:hover {
  transform: scale(1.1);
}

.pg-detail-title {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text);
}

.pg-detail-feeds {
  font-size: 0.7rem;
  color: var(--text-muted);
  margin-top: 0.2rem;
}

@media (max-width: 768px) {
  .pg-header {
    padding: 1rem 1.5rem;
    flex-direction: column;
    gap: 1rem;
    align-items: flex-start;
  }

  .pg-header-right {
    width: 100%;
    justify-content: space-between;
  }

  .pg-search-input {
    width: 120px;
  }

  .pg-slider-bar {
    padding: 1rem 1.5rem;
    flex-direction: column;
    gap: 1.2rem;
    align-items: flex-start;
  }

  .pg-slider-wrap {
