  --bg-card: #111;
  --text: var(--primary-light);  /* 随主题色变化 */
  --text-muted: #888;
  --border: #333;
  --glass: rgba(0, 0, 0, .8);
  --glass-border: rgba(255, 255, 255, .1);
  background-color: #000;
