/* Stars Effect - Pure container, stars generated by JS */
#nm-stars {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: -2;
  background: transparent;
  overflow: hidden;
}

/* Individual star dots created by JS */
#nm-stars .nm-star {
  position: absolute;
  border-radius: 50%;
  background: #fff;
  animation: nmStarTwinkle var(--dur, 2s) var(--delay, 0s) infinite ease-in-out;
}

@keyframes nmStarTwinkle {
  0%, 100% { opacity: var(--min-op, 0.2); transform: scale(1); }
  50% { opacity: var(--max-op, 1); transform: scale(1.5); }
}

/* Aurora Effect */
#nm-aurora {
  position: fixed;
  top: -20vh;
  left: -20vw;
  width: 140vw;
  height: 140vh;
  pointer-events: none;
  z-index: -1;
  opacity: 0.3;
  background: radial-gradient(ellipse at 50% 30%, rgba(46,204,113,0.3) 0%, rgba(52,152,219,0.2) 40%, transparent 70%),
              radial-gradient(ellipse at 80% 60%, rgba(155,89,182,0.3) 0%, transparent 60%);
  filter: blur(80px);
  animation: nmAurora 12s infinite alternate ease-in-out;
}

@keyframes nmStars {
  from { background-position: 0 0; }
  to { background-position: -400px -400px; }
}

@keyframes nmAurora {
  0% { transform: scale(1) translate(0, 0) rotate(0deg); opacity: 0.2; }
  50% { transform: scale(1.1) translate(2%, 3%) rotate(2deg); opacity: 0.4; }
  100% { transform: scale(1) translate(-2%, -1%) rotate(-1deg); opacity: 0.3; }
}

/* Low-performance device overrides */
.low-perf .student-card {
  transition: none !important;
}
.low-perf .student-card:hover {
  transform: none !important;
}
.low-perf * {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ══════════════════ COUNTDOWN TIMER ══════════════════ */
.cd-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 35%, rgba(60, 20, 110, .92), rgba(15, 5, 35, .96));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  opacity: 0;
  transition: opacity .3s ease;
  padding: env(safe-area-inset-top, 1rem) 1rem env(safe-area-inset-bottom, 1rem);
  overflow-y: auto;
}
.cd-overlay.open {
  opacity: 1;
}
.cd-overlay-inner {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(1rem, 3vmin, 2rem);
  width: 100%;
  max-width: 560px;
  padding: clamp(1.2rem, 4vmin, 2.5rem);
  transform: scale(.92);
  transition: transform .3s cubic-bezier(.34, 1.56, .64, 1);
}
.cd-overlay.open .cd-overlay-inner {
  transform: scale(1);
}

.cd-close {
  position: absolute;
  top: 0;
  right: 0;
  width: clamp(38px, 8vmin, 48px);
  height: clamp(38px, 8vmin, 48px);
  border-radius: 50%;
  background: rgba(255, 255, 255, .12);
  color: #fff;
  font-size: clamp(1rem, 3vmin, 1.4rem);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .2s, transform .2s;
}
.cd-close:hover {
  background: rgba(255, 255, 255, .25);
  transform: rotate(90deg);
}

/* Ring + display */
.cd-ring-wrap {
  position: relative;
  width: clamp(220px, 60vmin, 340px);
  height: clamp(220px, 60vmin, 340px);
  display: flex;
  align-items: center;
  justify-content: center;
}
.cd-ring {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.cd-ring-bg {
  fill: none;
  stroke: rgba(255, 255, 255, .12);
  stroke-width: 12;
}
.cd-ring-fg {
  fill: none;
  stroke: url(#cd-grad);
  stroke: #a78bfa;
  stroke-width: 12;
  stroke-linecap: round;
  transition: stroke-dashoffset 1s linear, stroke .3s;
}
.cd-display {
  position: absolute;
  font-size: clamp(3rem, 18vmin, 6.5rem);
  font-weight: 800;
  color: #fff;
  font-variant-numeric: tabular-nums;
  letter-spacing: .02em;
  text-shadow: 0 4px 24px rgba(167, 139, 250, .5);
  line-height: 1;
}
.cd-display.cd-warning {
  color: #fca5a5;
  animation: cdPulse .5s ease-in-out infinite;
}
.cd-display.cd-finished {
  color: #6ee7b7;
  animation: cdFinishedFlash 1s ease-in-out infinite;
}
@keyframes cdPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}
@keyframes cdFinishedFlash {
  0%, 100% { opacity: 1; }
  50% { opacity: .4; }
}

/* Presets */
.cd-presets {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(.4rem, 1.5vmin, .7rem);
  justify-content: center;
}
.cd-preset {
  padding: clamp(.4rem, 1.5vmin, .6rem) clamp(.8rem, 3vmin, 1.3rem);
  border-radius: 999px;
  background: rgba(255, 255, 255, .1);
  color: #e9d5ff;
  font-weight: 600;
  font-size: clamp(.8rem, 2.4vmin, 1rem);
  border: 1.5px solid rgba(255, 255, 255, .18);
  transition: all .2s;
}
.cd-preset:hover {
  background: rgba(255, 255, 255, .2);
  color: #fff;
}
.cd-preset.active {
  background: linear-gradient(135deg, #8b5cf6, #a855f7);
  color: #fff;
  border-color: transparent;
  box-shadow: 0 4px 14px rgba(168, 85, 247, .5);
}

/* Custom input */
.cd-custom {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(.4rem, 1.5vmin, .6rem);
  color: #e9d5ff;
  font-size: clamp(.85rem, 2.4vmin, 1rem);
}
.cd-custom label {
  font-weight: 600;
}
.cd-num {
  width: clamp(56px, 16vmin, 80px);
  text-align: center;
  padding: clamp(.35rem, 1.5vmin, .55rem);
  border-radius: 10px;
  border: 1.5px solid rgba(255, 255, 255, .25);
  background: rgba(255, 255, 255, .12);
  color: #fff;
  font-size: clamp(.9rem, 2.6vmin, 1.1rem);
  font-weight: 700;
}
.cd-num:focus {
  border-color: #a78bfa;
  background: rgba(255, 255, 255, .2);
  box-shadow: 0 0 0 3px rgba(167, 139, 250, .3);
}
.cd-custom .btn-ghost {
  background: rgba(255, 255, 255, .15);
  color: #fff;
  border-color: rgba(255, 255, 255, .3);
}
.cd-custom .btn-ghost:hover {
  background: rgba(255, 255, 255, .28);
  color: #fff;
}

/* Controls */
.cd-controls {
  display: flex;
  gap: clamp(.6rem, 2vmin, 1rem);
  flex-wrap: wrap;
  justify-content: center;
}
.cd-btn {
  padding: clamp(.6rem, 2vmin, .9rem) clamp(1.5rem, 5vmin, 2.5rem);
  border-radius: 999px;
  font-weight: 700;
  font-size: clamp(.95rem, 2.8vmin, 1.2rem);
  transition: all .2s;
  min-width: clamp(120px, 30vmin, 160px);
}
.cd-btn-primary {
  background: linear-gradient(135deg, #8b5cf6, #7c3aed);
  color: #fff;
  box-shadow: 0 4px 16px rgba(124, 58, 237, .5);
}
.cd-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(124, 58, 237, .6);
}
.cd-btn-ghost {
  background: rgba(255, 255, 255, .12);
  color: #fff;
  border: 1.5px solid rgba(255, 255, 255, .25);
}
.cd-btn-ghost:hover {
  background: rgba(255, 255, 255, .22);
  transform: translateY(-2px);
}

/* Landscape on short screens: shrink ring, side-by-side layout */
@media (max-height: 520px) and (orientation: landscape) {
  .cd-overlay-inner {
    flex-direction: row;
    flex-wrap: wrap;
    max-width: 92vw;
    gap: clamp(.8rem, 3vmin, 1.5rem);
  }
  .cd-ring-wrap {
    width: clamp(160px, 40vmin, 240px);
    height: clamp(160px, 40vmin, 240px);
  }
  .cd-display {
    font-size: clamp(2.2rem, 12vmin, 4rem);
  }
}

/* ── 宠物背景库弹窗 ── */
.petbg-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: .75rem;
  padding: .5rem 0 .25rem;
}

.petbg-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .35rem;
  background: none;
  border: 2px solid var(--border);
  border-radius: 10px;
  padding: .45rem .3rem;
  cursor: pointer;
  transition: border-color .18s, box-shadow .18s;
}

.petbg-item:hover {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(var(--primary-rgb), .15);
}

.petbg-item--active {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(var(--primary-rgb), .25);
}

.petbg-thumb {
  width: 90px;
  height: 70px;
  object-fit: cover;
  border-radius: 7px;
}

.petbg-thumb--default {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(var(--primary-rgb), .08) 0%, transparent 100%);
  border: 1.5px dashed var(--border);
  font-size: .78rem;
  color: var(--text-muted);
  border-radius: 7px;
}

.petbg-label {
  font-size: .73rem;
  color: var(--text-muted);
  text-align: center;
  line-height: 1.2;
}

/* 锁定状态 */
.petbg-item--locked {
  opacity: .75;
  cursor: not-allowed;
}

.petbg-item--locked:hover {
  border-color: var(--border);
  box-shadow: none;
}

.petbg-thumb--locked {
  position: relative;
  width: 90px;
  height: 70px;
  border-radius: 7px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,.08);
}

.petbg-thumb-blur {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: blur(3px) brightness(.55);
  border-radius: 7px;
}

.petbg-lock-icon {
  position: relative;
  z-index: 1;
  font-size: 1.6rem;
  line-height: 1;
}

/* ─────── 座位调整模式 ─────── */
#btn-seat-edit.active {
  background: linear-gradient(135deg, #a78bfa, #7c3aed);
  color: #fff;
  border-color: transparent;
  box-shadow: 0 4px 12px rgba(124, 58, 237, .35);
}

.students-grid.seat-edit-mode .student-card {
  cursor: grab;
  transition: transform .18s ease, box-shadow .18s ease;
}
.students-grid.seat-edit-mode .student-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(124, 58, 237, .18);
}
.students-grid.seat-edit-mode .student-card:active {
  cursor: grabbing;
}
.students-grid.seat-edit-mode .student-card.seat-dragging {
  opacity: .55;
  transform: scale(.97);
}
.students-grid.seat-edit-mode .student-card.seat-drop-target {
  outline: 2px dashed #7c3aed;
  outline-offset: 3px;
  background: rgba(124, 58, 237, .06);
}

/* 调整座位按钮内嵌的物理开关 */
#btn-seat-edit { display: inline-flex; align-items: center; gap: 6px; }
#btn-seat-edit .seat-switch {
  position: relative;
  display: inline-block;
  width: 28px;
  height: 16px;
  background: #d1d5db;
  border-radius: 999px;
  transition: background .2s ease;
  vertical-align: middle;
  flex-shrink: 0;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .15);
}
#btn-seat-edit .seat-switch-knob {
  position: absolute;
  top: 1px;
  left: 1px;
  width: 14px;
  height: 14px;
  background: #ffffff;
  border-radius: 50%;
  transition: transform .2s ease;
  box-shadow: 0 1px 2px rgba(0, 0, 0, .25);
}
#btn-seat-edit.active .seat-switch {
  background: #7c3aed;
}
#btn-seat-edit.active .seat-switch-knob {
  transform: translateX(12px);
}

/* 调整行数：无极滑块弹层 */
.grid-density-popover {
  z-index: 9999;
  background: rgba(255, 255, 255, 0.55);
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  border-radius: 12px;
  padding: 12px 14px;
  min-width: 240px;
  color: #333;
  animation: gdp-fade-in .18s ease-out;
}
@keyframes gdp-fade-in {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}
.grid-density-popover .gdp-title {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 8px;
  color: #444;
}
.grid-density-popover .gdp-range {
  width: 100%;
  appearance: none;
  -webkit-appearance: none;
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(to right, rgba(124, 58, 237, 0.35), rgba(124, 58, 237, 0.75));
  outline: none;
  cursor: pointer;
}
.grid-density-popover .gdp-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid #7c3aed;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
  cursor: pointer;
}
.grid-density-popover .gdp-range::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid #7c3aed;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
  cursor: pointer;
}
.grid-density-popover .gdp-hint {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #666;
  margin-top: 6px;
}

/* 卡片密度：使用 zoom 等比缩放，保持原始长宽比例 */
#students-grid .student-card {
  zoom: var(--card-zoom, 1);
}

